# Definición de colores ANSI para la terminal
# ===== TEMA TEMPLEOS =====
# Pon TEMPLE_MODE = False para volver a la terminal normal.
TEMPLE_MODE = True
THEME = "\033[44;97m" if TEMPLE_MODE else ""   # Fondo azul VGA + texto blanco
RESET = "\033[0m" + THEME   # Al resetear, vuelve a pintar el azul de fondo
BOLD = "\033[1m"
WHITE = "\033[97m"
MAGENTA = "\033[95m"  # Fucsia / Magenta para comandos
CYAN = "\033[96m" if TEMPLE_MODE else "\033[36m"     # Cian para bordes y títulos
GREEN = "\033[92m"    # Verde para estados correctos y éxito
YELLOW = "\033[93m"   # Amarillo para datos y advertencias
RED = "\033[91m"      # Rojo para errores

# ===== VERSIÓN =====
