# ===== PINTOR DE FONDO (arregla las zonas negras) =====
# Muchas terminales (Windows con ventana semitransparente, Pydroid 3...) solo pintan el
# fondo azul DETRÁS de las letras; el resto de cada línea nueva queda negro/transparente.
# Este filtro rellena cada línea con espacios del color de fondo del tema.
SCREEN_COLS = 0   # 0 = detectar solo. Si en Pydroid 3 aún ves negro, pon aquí el ancho (ej. 45)

_TOKEN_RE = re.compile(r"(\x1b\[[0-9;?]*[@-~]|\n|\r|\t|\x08)")


def _term_cols():
    if SCREEN_COLS > 0:
        return SCREEN_COLS
    try:
        cols = shutil.get_terminal_size((0, 0)).columns
        if cols > 0:
            return cols
    except Exception:
        pass
    for fd in (1, 0, 2):
        try:
            return os.get_terminal_size(fd).columns
        except Exception:
            pass
    return 0


def _term_rows():
    try:
        rows = shutil.get_terminal_size((0, 0)).lines
        if rows > 0:
            return rows
    except Exception:
        pass
    for fd in (1, 0, 2):
        try:
            return os.get_terminal_size(fd).lines
        except Exception:
            pass
    return 0


def _char_w(ch):
    if ch < " " or ch == "\x7f" or unicodedata.combining(ch):
        return 0
    return 2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1


class _PaintedStdout:
    """Envuelve sys.stdout: al terminar cada línea la rellena con el fondo del tema."""

    def __init__(self, real):
        self._real = real
        self.col = 0          # columna actual del cursor (aprox.)

    def __getattr__(self, name):
        return getattr(self._real, name)

    def flush(self):
        self._real.flush()

    def _fill(self):
        """Pinta lo que falta de la línea (se usa justo antes de un salto de línea)."""
        cols = _term_cols()
        if not cols:
            return "\033[K"
        c = self.col % cols
        if self.col and not c:
            return ""         # la línea llenó justo el ancho: no hay nada que pintar
        n = cols - 1 - c
        return (" " * n if n > 0 else "") + "\033[K"

    def fill_inline(self):
        """Pinta el resto de la línea actual y devuelve el cursor a donde estaba."""
        cols = _term_cols()
        if not cols:
            return "\033[K"
        c = self.col % cols
        n = cols - 1 - c
        if n <= 0:
            return "\033[K"
        back = "\r" if self.col == 0 else "\033[%dD" % n
        return " " * n + "\033[K" + back

    def _track(self, seq):
        final, nums = seq[-1], seq[2:-1]
        if nums.startswith("?"):
            return
        p = [int(x) if x.isdigit() else 0 for x in nums.split(";")] if nums else []
        n = p[0] if p and p[0] else 1
        if final in "Hf":
            self.col = (p[1] - 1) if len(p) > 1 and p[1] > 0 else 0
        elif final == "G":
            self.col = max(0, n - 1)
        elif final == "C":
            self.col += n
        elif final == "D":
            self.col = max(0, self.col - n)

    def write(self, s):
        if not s:
            return 0
        paint = bool(THEME)
        out = []
        for tok in _TOKEN_RE.split(s):
            if not tok:
                continue
            if tok == "\n":
                if paint:
                    out.append(self._fill())
                out.append("\n")
                self.col = 0
            elif tok == "\r":
                out.append(tok)
                self.col = 0
            elif tok == "\t":
                out.append(tok)
                self.col = (self.col // 8 + 1) * 8
            elif tok == "\x08":
                out.append(tok)
                self.col = max(0, self.col - 1)
            elif tok[0] == "\x1b":
                out.append(tok)
                self._track(tok)
            else:
                out.append(tok)
                if tok.isascii() and tok.isprintable():
                    self.col += len(tok)
                else:
                    self.col += sum(_char_w(ch) for ch in tok)
        self._real.write("".join(out))
        return len(s)

    def raw(self, s):
        """Escribe sin filtrar (para clear_screen)."""
        self._real.write(s)
        self.col = 0


_orig_input = builtins.input


def _painted_input(prompt=""):
    """input() que antes pinta la línea completa con el fondo del tema."""
    prompt = "" if prompt is None else str(prompt)
    out = sys.stdout
    if THEME and isinstance(out, _PaintedStdout):
        head, sep, last = prompt.rpartition("\n")
        if sep:
            out.write(head + "\n")
        out._real.write(out.fill_inline())
        out._real.flush()
        prompt = last
    try:
        try:
            tty = sys.stdin is not None and sys.stdin.isatty()
        except Exception:
            tty = False
        if _RL_WRAP and tty:
            prompt = _ANSI_PROMPT_RE.sub("\001\\g<0>\002", prompt)
        return _orig_input(prompt)
    finally:
        if isinstance(out, _PaintedStdout):
            out.col = 0


def _install_painter():
    if sys.stdout is None or isinstance(sys.stdout, _PaintedStdout):
        return
    if os.name == "nt":
        os.system("")         # activa los códigos ANSI en la consola de Windows
    sys.stdout = _PaintedStdout(sys.stdout)
    builtins.input = _painted_input


_install_painter()


