def clear_screen():
    # Limpieza por ANSI (compatible con Pydroid 3) y pintado completo del fondo.
    # \033[2J borra toda la pantalla y \033[3J borra el historial (scrollback),
    # asi al subir con el dedo no aparece nada de lo anterior.
    seq = "\033[0m" + THEME + "\033[H\033[2J\033[3J"
    cols, rows = _term_cols(), _term_rows()
    if THEME and cols > 1 and rows > 1:
        blank = " " * (cols - 1) + "\033[K"
        seq += "\n".join([blank] * rows) + "\033[H"
    out = sys.stdout
    if isinstance(out, _PaintedStdout):
        out.raw(seq)
    else:
        out.write(seq)
    out.flush()

