def login_system():
    clear_screen()
    panel("EL UMBRAL DEL TEMPLO")
    print()
    typewriter(f"{YELLOW}Alto, viajero. Soy la Serpiente Guardiana del Umbral.{RESET}", 0.02)
    time.sleep(0.4)
    typewriter(f"{CYAN}Nadie entra al templo sin decir su nombre.{RESET}", 0.02)
    print()

    username = input(f"{CYAN}¿Cómo te llamas, viajero? {YELLOW}").strip()
    print(RESET, end="")
    if not username:
        username = "user"
        print(f"{YELLOW}Silencio... entonces te llamaré '{username}'.{RESET}")
    else:
        print(f"{GREEN}" + random.choice(LOGIN_GREETINGS).format(u=username) + f"{RESET}")
    time.sleep(0.6)
    print()

    typewriter(f"{CYAN}Ahora susurra la palabra sagrada...{RESET}", 0.02)
    attempts = 3
    while attempts > 0:
        vidas = "◆" * attempts + "◇" * (3 - attempts)
        print(f"{WHITE}Aliento de la serpiente: {YELLOW}{vidas}{RESET}")
        password = input(f"{CYAN}Palabra sagrada de {YELLOW}{username}{CYAN}: {RESET}").strip()
        if password == system_state["password"]:
            print()
            for i in range(21):
                bar = "█" * i + "░" * (20 - i)
                sys.stdout.write(f"\r{CYAN}Abriendo el portal [{YELLOW}{bar}{CYAN}]{RESET} {i * 5:>3}%")
                sys.stdout.flush()
                time.sleep(0.05)
            print(f"\n\n{GREEN}¡Las puertas se abren! Bienvenido al templo, {username}.{RESET}")
            time.sleep(1)
            return username
        else:
            attempts -= 1
            if attempts > 0:
                print(f"{RED}{random.choice(LOGIN_FAILS)}{RESET}\n")
            else:
                print(f"\n{RED}La serpiente abre la boca... ¡Te devora! Sistema bloqueado.{RESET}")
                sys.exit(0)


def resolve_path(arg):
    """Permite interpretar rutas como a:archivo.txt o b:notas.txt"""
    arg = arg.strip().upper()
    if not arg:
        return current_drive, ""
    if ":" in arg:
        parts = arg.split(":", 1)
        drive = parts[0]
        filename = parts[1].lstrip("\\/")
        if drive in disks_storage:
            return drive, filename
    return current_drive, arg.lstrip("\\/")

