# ===== RATÓN EN LA TERMINAL (help clicable con resaltado) =====
_MOUSE_ON = "\033[?1000h\033[?1003h\033[?1006h\033[?25l"
_MOUSE_OFF = "\033[?1003l\033[?1000l\033[?1006l\033[?25h"
_HOVER = "\033[0;30;106m\033[1m"      # resaltado: texto negro sobre cian


def _raw_out(s):
    out = getattr(sys.stdout, "_real", sys.stdout)
    out.write(s)
    out.flush()


def _mouse_off():
    try:
        _raw_out(_MOUSE_OFF)
    except Exception:
        pass


def _mouse_capable():
    try:
        return sys.stdin.isatty() and sys.stdout is not None
    except Exception:
        return False


class _RawInput:
    """Lee la terminal en modo crudo con eventos de ratón (SGR 1006)."""
    def __enter__(self):
        if os.name == "nt":
            import ctypes
            from ctypes import wintypes
            self.k32 = ctypes.windll.kernel32
            self.h = self.k32.GetStdHandle(-10)
            self.old = wintypes.DWORD()
            self.k32.GetConsoleMode(self.h, ctypes.byref(self.old))
            # VT_INPUT(0x200) + EXTENDED_FLAGS(0x80) sin QUICK_EDIT/LINE/ECHO
            self.k32.SetConsoleMode(self.h, 0x200 | 0x80)
            self.ctypes, self.wt = ctypes, wintypes
        else:
            import termios, tty
            self.fd = sys.stdin.fileno()
            self.old = termios.tcgetattr(self.fd)
            tty.setraw(self.fd)
        _raw_out(_MOUSE_ON)
        return self

    def __exit__(self, *a):
        _mouse_off()
        if os.name == "nt":
            self.k32.SetConsoleMode(self.h, self.old)
        else:
            import termios
            termios.tcsetattr(self.fd, termios.TCSADRAIN, self.old)

    def read(self):
        if os.name == "nt":
            buf = self.ctypes.create_unicode_buffer(128)
            n = self.wt.DWORD()
            self.k32.ReadConsoleW(self.h, buf, 128, self.ctypes.byref(n), None)
            return buf.value[: n.value]
        import select
        data = os.read(self.fd, 256)
        while select.select([self.fd], [], [], 0.02)[0]:
            data += os.read(self.fd, 256)
        return data.decode(errors="ignore")


_EVT_RE = re.compile(r"\x1b\[<(\d+);(\d+);(\d+)([Mm])|\x1b\[(\d*)([A-Z~])|\x1bO([A-Z])|\x1b|.", re.S)


def _parse_events(data):
    evs = []
    for m in _EVT_RE.finditer(data):
        if m.group(1):
            b, x, y, kind = int(m.group(1)), int(m.group(2)), int(m.group(3)), m.group(4)
            if b == 64:
                evs.append(("wheel", -3))
            elif b == 65:
                evs.append(("wheel", 3))
            elif b & 32:
                evs.append(("move", y))
            elif kind == "M" and (b & 3) == 0:
                evs.append(("click", y))
        elif m.group(6) or m.group(7):
            k = (m.group(5) or "") + (m.group(6) or m.group(7))
            evs.append(("key", {"A": "up", "B": "down", "5~": "pgup", "6~": "pgdn"}.get(k, "")))
        else:
            ch = m.group(0)
            if ch in ("\r", "\n"):
                evs.append(("key", "enter"))
            elif ch in ("\x1b", "q", "Q", "\x03"):
                evs.append(("key", "esc"))
    return evs


def _help_interactivo(secciones):
    """Muestra help a pantalla completa. Devuelve la línea de comando elegida o None."""
    filas = []   # (texto_plano, comando o None, es_titulo)
    for titulo, cmds in secciones:
        filas.append((f"══ {titulo} " + "═" * max(0, 52 - len(titulo)), None, True))
        for c, d in cmds:
            first = c.split("/")[0].split("[")[0].strip().split()
            filas.append((f"  {c:<16} {d}", first[0] if first else None, False))
    sel_idx = [i for i, f in enumerate(filas) if f[1]]
    state = {"top": 0, "hover": -1}
    TOP = 3   # filas 1-2: cabecera

    def view_h():
        return max(3, _term_rows() - TOP - 1)

    def render_row(i):
        """Redibuja una sola fila, sin limpiar toda la pantalla en cada movimiento."""
        cols = max(1, _term_cols())
        bg = THEME or "\033[0m"
        r = i - state["top"]
        if not 0 <= r < view_h():
            return ""
        if i >= len(filas):
            line = f"{bg}{' ' * cols}{RESET}"
        else:
            txt, cmd, is_t = filas[i]
            txt = txt[:cols]
            if is_t:
                line = f"{bg}{CYAN}{BOLD}{txt.ljust(cols)}{RESET}"
            elif i == state["hover"]:
                line = f"{_HOVER}{('> ' + txt[2:])[:cols].ljust(cols)}{RESET}"
            else:
                line = f"{bg}  {MAGENTA}{txt[2:18]}{RESET}{bg}{txt[18:].ljust(max(0, cols - 18))}"
        return f"\033[{TOP + r};1H{line}"

    def draw():
        cols, h = max(1, _term_cols()), view_h()
        bg = THEME or "\033[0m"
        out = ["\033[H", bg, "\033[2J"]
        head = " AYUDA DE SERPENT OS  -  pasa el ratón por un comando y haz clic "
        out.append(f"\033[1;1H{bg}{CYAN}{BOLD}{head[:cols].ljust(cols)}{RESET}")
        out.append(f"\033[2;1H{bg}{' ' * cols}{RESET}")
        for r in range(h):
            out.append(render_row(state["top"] + r))
        foot = " ↑↓/rueda: moverse   clic/Enter: ejecutar   Esc/q: salir "
        out.append(f"\033[{TOP + h};1H{bg}{YELLOW}{foot[:cols].ljust(cols)}{RESET}")
        _raw_out("".join(out))

    def ensure_visible():
        h = view_h()
        if state["hover"] < state["top"]:
            state["top"] = state["hover"]
        elif state["hover"] >= state["top"] + h:
            state["top"] = state["hover"] - h + 1

    def row_to_idx(y):
        i = state["top"] + (y - TOP)
        if TOP <= y < TOP + view_h() and 0 <= i < len(filas):
            return i
        return -1

    with _RawInput() as raw:
        draw()
        while True:
            redraw = False
            for kind, val in _parse_events(raw.read()):
                if kind == "move":
                    i = row_to_idx(val)
                    if i >= 0 and filas[i][1] and i != state["hover"]:
                        previous = state["hover"]
                        state["hover"] = i
                        # Solo se repintan la fila anterior y la nueva.
                        _raw_out(render_row(previous) + render_row(i))
                    elif (i < 0 or not filas[i][1]) and state["hover"] >= 0:
                        previous = state["hover"]
                        state["hover"] = -1
                        _raw_out(render_row(previous))
                elif kind == "click":
                    i = row_to_idx(val)
                    if i >= 0 and filas[i][1]:
                        clear_screen()
                        return filas[i][1]
                elif kind == "wheel":
                    mx = max(0, len(filas) - view_h())
                    state["top"] = min(mx, max(0, state["top"] + val))
                    redraw = True
                elif kind == "key":
                    if val == "esc":
                        clear_screen()
                        return None
                    if val == "enter" and state["hover"] >= 0:
                        clear_screen()
                        return filas[state["hover"]][1]
                    if val in ("up", "down", "pgup", "pgdn") and sel_idx:
                        step = {"up": -1, "down": 1, "pgup": -10, "pgdn": 10}[val]
                        pos = sel_idx.index(state["hover"]) if state["hover"] in sel_idx else 0
                        pos = min(len(sel_idx) - 1, max(0, pos + step))
                        state["hover"] = sel_idx[pos]
                        ensure_visible()
                        redraw = True
            if redraw:
                draw()

