    if not drive_letter:
        print(f"{RED}Uso: mount [a/b]{RESET}")
        return
    drive = drive_letter.upper()
    if drive in disks_storage:
        print(f"{YELLOW}* Click-clack * Seleccionando unidad {drive}: como activa...{RESET}")
