_EDIT_CMD_RE = re.compile(r"^:(l|d|r|i|c|h)(?:\s+(\d+))?(?:\s+(.*))?$")


def _edit_command(lines, m):
    cmd, num, text = m.group(1), m.group(2), m.group(3)
    n = int(num) if num else 0
    if cmd == "l":
        if not lines:
            print(f"{YELLOW}(archivo vacío){RESET}")
        for i, ln in enumerate(lines, 1):
            print(f"{CYAN}{i:>3}{RESET} {ln}")
    elif cmd == "d":
        if 1 <= n <= len(lines):
            removed = lines.pop(n - 1)
            print(f"{GREEN}Línea {n} borrada: {removed[:40]}{RESET}")
        else:
            print(f"{RED}Uso: :d N   (N entre 1 y {len(lines)}){RESET}")
    elif cmd == "r":
        if 1 <= n <= len(lines) and text is not None:
            lines[n - 1] = text
            print(f"{GREEN}Línea {n} reemplazada.{RESET}")
        else:
            print(f"{RED}Uso: :r N nuevo texto{RESET}")
    elif cmd == "i":
        if 1 <= n <= len(lines) + 1 and text is not None:
            lines.insert(n - 1, text)
            print(f"{GREEN}Línea insertada en la posición {n}.{RESET}")
        else:
            print(f"{RED}Uso: :i N texto   (inserta antes de la línea N){RESET}")
    elif cmd == "c":
        lines.clear()
        print(f"{GREEN}Contenido vaciado (se aplica al guardar con :wq).{RESET}")
    else:
        print(f"{CYAN}:wq{RESET} guardar y salir | {CYAN}:q{RESET} salir sin guardar | {CYAN}:l{RESET} listar | "
              f"{CYAN}:d N{RESET} borrar | {CYAN}:r N texto{RESET} reemplazar | {CYAN}:i N texto{RESET} insertar | {CYAN}:c{RESET} vaciar")


def cmd_edit(args):
    if not args:
        print(f"{RED}Uso: edit [unidad:]nombre_de_archivo (ej. edit b:notas.txt){RESET}")
        return
    
    target_drive, filename = resolve_path(args)
    if not filename:
        print(f"{RED}Error: Nombre de archivo no válido.{RESET}")
        return
    
    print(f"{CYAN}--- Abriendo editor multilínea para [{target_drive}:\\{filename}] ---{RESET}")
    print(f"{YELLOW}Escribe tu texto línea por línea. ':wq' guarda y sale, ':q' sale, ':h' = ayuda del editor.{RESET}")
    print("-" * 55)
    
    existing_content = disks_storage[target_drive]["files"].get(filename, "")
    lines = existing_content.split("\n") if existing_content else []
    
    if existing_content:
        print(f"{GREEN}(El archivo ya tiene contenido previo){RESET}")
    
    while True:
        try:
            line_input = input(f"{MAGENTA}]{RESET} ")
            if line_input == ":wq":
                final_text = "\n".join(lines)
                _files = disks_storage[target_drive]["files"]
                _old = file_size(target_drive, filename) if filename in _files else 0
                if len(final_text.encode("utf-8")) - _old > disk_free(target_drive):
                    print(f"{RED}No hay espacio suficiente en {target_drive}:. Escribe ':q' para salir sin guardar.{RESET}")
                    continue
                disks_storage[target_drive]["files"][filename] = final_text
                print(f"{GREEN}* Bzzzt-bzzzt * Archivo '{filename}' guardado con éxito en {target_drive}:.{RESET}")
                break
            elif line_input == ":q":
                print(f"{YELLOW}Saliendo sin guardar cambios.{RESET}")
                break
            elif _EDIT_CMD_RE.match(line_input):
                _edit_command(lines, _EDIT_CMD_RE.match(line_input))
            else:
                lines.append(line_input)
        except KeyboardInterrupt:
            print(f"\n{RED}Editor interrumpido. Cambios descartados.{RESET}")
            break

def cmd_read(args):
    if not args:
        print(f"{RED}Uso: read [unidad:]nombre_de_archivo (ej. read a:leeme.txt){RESET}")
        return
    
    target_drive, filename = resolve_path(args)
    files = disks_storage[target_drive]["files"]
    if filename in files:
        if _capturing():            # dentro de una tubería (read x | grep y) solo sale el contenido
            print(files[filename])
            return
        print(f"\n{CYAN}--- Contenido de {target_drive}:\\{filename} ---{RESET}")
        print(f"{YELLOW}{files[filename]}{RESET}")
        print("-" * 35 + "\n")
    else:
        print(f"{RED}Error: El archivo '{filename}' no existe en el diskette {target_drive}:.{RESET}")

