def cmd_ps():
    KERNEL._update_cpu()
    panel("ADMINISTRADOR DE TAREAS")
    print(f"{BOLD}{'PID':>5} {'PPID':>5} {'S':<2}{'NI':>3} {'RSS':>7} {'TIEMPO':>9} {'CPU':>6} {'INS':>8}  NOMBRE{RESET}")
    print("-" * 69)
    colors = {"R": GREEN, "S": YELLOW, "T": RED, "Z": RED}
    for p in active_processes:
        st = p.get("state", "?")
        rss = KERNEL.pages_of(p["pid"]) * KERNEL.PAGE_KB
        print(f"{p['pid']:>5} {p.get('ppid', 0):>5} {colors.get(st, WHITE)}{st:<2}{RESET}{p.get('prio', 10):>3} "
              f"{rss:>6}K {p.get('cpu_ns', 0) / 1e6:>7.1f}ms {YELLOW}{p['cpu']:>6}{RESET} "
              f"{p.get('instructions', 0):>8}  {MAGENTA}{p['name']}{RESET}")
    print("")

def cmd_kill(args):
    parts = args.split()
    if not parts:
        print(f"{RED}Uso: kill [-SEÑAL] PID   (ej. kill 3, kill -9 3, kill -STOP 3){RESET}")
        return
    sig = SIGTERM
    if parts[0].startswith("-"):
        spec = parts.pop(0)[1:].upper()
        names = {v[3:]: k for k, v in SIGNAL_NAMES.items()}
        sig = int(spec) if spec.isdigit() else names.get(spec.replace("SIG", ""), -1)
        if sig not in SIGNAL_NAMES:
            print(f"{RED}Señal desconocida. Válidas: " + ", ".join(f"{k}={v}" for k, v in SIGNAL_NAMES.items()) + RESET)
            return
    if not parts or not parts[0].isdigit():
        print(f"{RED}Error: El PID debe ser un número entero válido.{RESET}")
        return
    pid = int(parts[0])
    p = KERNEL._proc(pid)
    name = p["name"] if p else "?"
    err = KERNEL.kill(pid, sig)
    if err == EPERM:
        print(f"{RED}kill: ({pid}) - Operación no permitida (EPERM): init está protegido.{RESET}")
    elif err == ESRCH:
        print(f"{RED}kill: ({pid}) - No existe el proceso (ESRCH).{RESET}")
    elif err:
        print(f"{RED}kill: error {ERRNO_NAMES.get(err, err)}{RESET}")
    else:
        print(f"{GREEN}{SIGNAL_NAMES[sig]} enviada a PID {pid} ({name}).{RESET}")

