def _anim_servicios():
    """Barras de progreso: se van apagando los servicios uno por uno."""
    servicios = [
        "Guardando sesión",
        "Deteniendo MatrixService",
        "Desmontando diskettes",
        "Durmiendo a la serpiente",
    ]
    for s in servicios:
        for i in range(11):
            bar = "█" * i + "░" * (10 - i)
            sys.stdout.write(f"\r {WHITE}[{GREEN}{bar}{WHITE}]{RESET} {s:<24}")
            sys.stdout.flush()
            time.sleep(0.02)
        print(f" {GREEN}OK{RESET}")
        time.sleep(0.12)


def _anim_serpiente(ancho=30, largo=9):
    """Una serpiente cruza la pantalla de izquierda a derecha y desaparece."""
    print()
    for pos in range(ancho + largo):
        celdas = []
        for x in range(ancho):
            i = pos - x                      # distancia a la cabeza
            if i == 0:
                celdas.append(f"{BOLD}{YELLOW}█")
            elif 0 < i < 3:
                celdas.append(f"{GREEN}▓")
            elif 3 <= i < 6:
                celdas.append(f"{GREEN}▒")
            elif 6 <= i < largo:
                celdas.append(f"{CYAN}░")
            else:
                celdas.append(f"{RESET} ")
        sys.stdout.write("\r " + "".join(celdas) + RESET)
        sys.stdout.flush()
        time.sleep(0.03)
    print("\n")


def _anim_crt(ancho=36):
    """La pantalla se aplasta en una línea y luego en un punto, como un monitor CRT."""
    for filas in (9, 7, 5, 3, 1):
        clear_screen()
        print("\n" * 3, end="")
        for _ in range(filas):
            print(f"{WHITE}" + ("█" * ancho).center(40) + f"{RESET}")
        time.sleep(0.07)
    for w in (ancho * 2 // 3, ancho // 3, 8, 3, 1):
        clear_screen()
        print("\n" * 6, end="")
        print(f"{WHITE}" + ("█" * w).center(40) + f"{RESET}")
        time.sleep(0.07)
    clear_screen()
    print("\n" * 6, end="")
    print(f"{WHITE}" + "·".center(40) + f"{RESET}")
    time.sleep(0.25)
    clear_screen()
    time.sleep(0.2)


def cmd_shutdown_sequence():
    serpent_event("Apagado solicitado", "info", "power")
    save_system()
    print(f"\n{GREEN}Iniciando secuencia de apagado seguro de Serpent OS...{RESET}")
    if save_system():
        print(f"{CYAN}Guardando diskettes y ajustes en el disco del host... {GREEN}OK{RESET}")
    time.sleep(0.4)
    try:
        _anim_servicios()
        _anim_serpiente()
        _anim_crt()
    except KeyboardInterrupt:
        # Ctrl+C salta la animación y apaga directamente
        clear_screen()
    print(f"{CYAN}Todo bit vuelve al templo.{RESET}")
    print(f"{YELLOW}Apagando Serpent OS. ¡Hasta luego!{RESET}")

def play_rpg_combat():
    print(f"\n{RED}--- ¡Un Goblin salvaje apareció en la mazmorra! ---{RESET}")
    player_hp = rpg_stats["max_hp"]
    goblin_hp = 20
    
    while player_hp > 0 and goblin_hp > 0:
        print(f"\n[{GREEN}Tus PV: {player_hp}/{rpg_stats['max_hp']}{RESET}] | [{RED}Goblin PV: {goblin_hp}/20{RESET}] | [{YELLOW}Pociones: {rpg_stats['potions']}{RESET}]")
        print(f"1. {MAGENTA}Atacar con espada ({rpg_stats['min_dmg']}-{rpg_stats['max_dmg']} dmg){RESET}")
        print(f"2. {MAGENTA}Usar poción (+10 HP){RESET}")
        print(f"3. {MAGENTA}Huir del combate{RESET}")
        
        choice = input("Acción (1-3): ").strip()
        
        if choice == "1":
            dmg = random.randint(rpg_stats["min_dmg"], rpg_stats["max_dmg"])
            goblin_hp -= dmg
            print(f"{GREEN}¡Atacas al goblin y le haces {dmg} de daño!{RESET}")
        elif choice == "2":
            if rpg_stats["potions"] > 0:
                player_hp = min(rpg_stats["max_hp"], player_hp + 10)
                rpg_stats["potions"] -= 1
                print(f"{GREEN}¡Poción usada! Recuperas 10 PV.{RESET}")
            else:
                print(f"{RED}¡No te quedan pociones!{RESET}")
                continue
        elif choice == "3":
            print(f"{YELLOW}¡Has huido de la mazmorra!{RESET}")
            return
        else:
            print(f"{RED}Opción no válida.{RESET}")
            continue
            
        if goblin_hp <= 0:
            reward = random.randint(12, 25)
            rpg_stats["gold"] += reward
            rpg_stats["wins"] += 1
            print(f"\n{GREEN}¡Victoria! Derrotaste al goblin y ganaste {reward} monedas de oro.{RESET}")
            break
            
        g_dmg = random.randint(3, 8)
        player_hp -= g_dmg
        print(f"{RED}El goblin contraataca y te hace {g_dmg} de daño.{RESET}")
        
        if player_hp <= 0:
            print(f"\n{RED}Has caído en combate... Game Over.{RESET}")
            break

