LINK_RE = re.compile(r"\[(\d+)\]")
ANSI_RE = re.compile(r"\x1b\[[0-9;]*m")


def shorten(text, limit):
    return text if len(text) <= limit else text[:max(1, limit - 3)] + "..."


class Page:
    """Una página ya procesada: bloques de texto + lista de enlaces."""

    def __init__(self, url, title=""):
        self.url = url
        self.title = title or url
        self.blocks = []    # lista de (tipo, texto): h, p, li, pre, hr
        self.links = []     # URLs; el enlace [n] es links[n-1]
        self.scroll = 0
        self.error = False
        self.image_preview = ""
        self.image_url = ""

    def add(self, kind, text=""):
        self.blocks.append((kind, text))

    def link(self, label, target):
        """Registra un enlace y devuelve el texto con su marcador [n]."""
        if target in self.links:
            idx = self.links.index(target) + 1
        else:
            self.links.append(target)
            idx = len(self.links)
        return f"{label}[{idx}]"


def error_page(url, message):
    page = Page(url, "Error")
    page.error = True
    page.add("h", "No se pudo cargar la página")
    page.add("p", f"Dirección: {url}")
    page.add("p", f"Motivo: {message}")
    page.add("li", page.link("Volver al inicio", "serpent://home"))
    return page


