# ---------------- Descarga de páginas web ----------------


def _wiki_search(query):
    """Busca información en Wikipedia usando su API oficial (sin raspar páginas HTML)."""
    api = "https://es.wikipedia.org/w/api.php?" + urllib.parse.urlencode({
        "action": "query", "generator": "search", "gsrsearch": query,
        "gsrlimit": 5, "prop": "extracts|pageimages|info",
        "exintro": 1, "explaintext": 1, "exchars": 1800,
        "pithumbsize": 420, "inprop": "url", "format": "json",
        "utf8": 1,
    })
    headers = {"User-Agent": "SerpentOS/5.8.1 (educational text browser)",
               "Accept": "application/json"}
    req = urllib.request.Request(api, headers=headers)
    ctx = ssl.create_default_context() if VERIFY_SSL else ssl._create_unverified_context()
    with urllib.request.urlopen(req, timeout=REQUEST_TIMEOUT, context=ctx) as resp:
        data = json.loads(resp.read(900_000).decode("utf-8", "replace"))
    pages = data.get("query", {}).get("pages", {})
    results = sorted(pages.values(), key=lambda p: p.get("index", 999))
    return results


def _make_image_preview(image_url, max_width=34, max_height=12):
    """Intenta convertir una imagen fija a bloques ANSI; si no hay Pillow, no falla."""
    if not image_url:
        return ""
    try:
        from PIL import Image
        req = urllib.request.Request(image_url, headers={"User-Agent": USER_AGENT})
        ctx = ssl.create_default_context() if VERIFY_SSL else ssl._create_unverified_context()
        with urllib.request.urlopen(req, timeout=REQUEST_TIMEOUT, context=ctx) as resp:
            raw = resp.read(450_000)
        import io
        im = Image.open(io.BytesIO(raw)).convert("RGB")
        im.thumbnail((max_width, max_height * 2))
        w, h = im.size
        lines = []
        for y in range(0, h - 1, 2):
            parts = []
            for x in range(w):
                top = im.getpixel((x, y))
                bottom = im.getpixel((x, min(y + 1, h - 1)))
                parts.append(f"\033[38;2;{top[0]};{top[1]};{top[2]}m"
                             f"\033[48;2;{bottom[0]};{bottom[1]};{bottom[2]}m▀")
            lines.append("".join(parts) + "\033[0m")
        return "\n".join(lines)
    except Exception:
        return ""


def build_search_page(query):
    """Página de resultados de texto plano con una miniatura opcional."""
    url = "serpent://search?q=" + urllib.parse.quote(query)
    page = Page(url, "Búsqueda: " + query)
    page.add("h", "RESULTADOS DE BÚSQUEDA")
    page.add("p", "Consulta: " + query)
    page.add("p", "Fuente: Wikipedia en español (API oficial).")
    try:
        results = _wiki_search(query)
        if not results:
            page.add("p", "No encontré resultados. Probá con otras palabras.")
            return page
        for i, item in enumerate(results[:5]):
            title = item.get("title", "Sin título")
            extract = re.sub(r"\s+", " ", item.get("extract", "")).strip()
            page.add("h", title)
            if extract:
                page.add("p", extract)
            else:
                page.add("p", "No hay resumen disponible para este resultado.")
            full_url = item.get("fullurl") or (
                "https://es.wikipedia.org/wiki/" + urllib.parse.quote(title.replace(" ", "_")))
            page.add("li", page.link("Leer artículo completo", full_url))
            thumb = item.get("thumbnail", {}).get("source", "")
            if i == 0 and thumb:
                page.image_url = thumb
                page.image_preview = _make_image_preview(thumb)
        if page.image_url and not page.image_preview:
            page.add("p", "Imagen fija disponible: " + page.image_url)
            page.add("p", "(No se pudo dibujar en esta terminal; abrí el enlace desde el artículo.)")
        page.add("p", "Los resúmenes son breves; abrí el artículo para ampliar.")
    except Exception as e:
        page.error = True
        page.add("p", "No se pudo consultar el servicio de búsqueda.")
        page.add("p", f"Detalle: {type(e).__name__}: {e}")
        page.add("p", "Comprobá tu conexión y volvé a intentar.")
    return page


def normalize_url(text):
    text = text.strip()
    if not text:
        return "serpent://home"
    low = text.lower()
    if re.match(r"^[a-z][a-z0-9+.\\-]*://", low):
        return text
    if " " not in text and "." in text:
        return "https://" + text
    return "serpent://search?q=" + urllib.parse.quote(text)


def fetch_url(url):
    """Descarga una URL. Devuelve (url_final, content_type, texto, truncado)."""
    headers = {
        "User-Agent": USER_AGENT,
        "Accept": "text/html,application/xhtml+xml,text/plain;q=0.9,*/*;q=0.5",
        "Accept-Language": "es,en;q=0.8",
    }
    req = urllib.request.Request(url, headers=headers)
    ctx = ssl.create_default_context() if VERIFY_SSL else ssl._create_unverified_context()
    with urllib.request.urlopen(req, timeout=REQUEST_TIMEOUT, context=ctx) as resp:
        raw = resp.read(MAX_BYTES + 1)
        ctype = (resp.headers.get("Content-Type") or "").lower()
        charset = resp.headers.get_content_charset()
        final_url = resp.geturl()
    truncated = len(raw) > MAX_BYTES
    raw = raw[:MAX_BYTES]
    if not charset:
        m = re.search(rb"charset=[\"']?([A-Za-z0-9_\-]+)", raw[:2048])
        charset = m.group(1).decode("ascii", "ignore") if m else "utf-8"
    try:
        text = raw.decode(charset, errors="replace")
    except LookupError:
        text = raw.decode("utf-8", errors="replace")
    return final_url, ctype, text, truncated


SKIP_TAGS = {"script", "style", "noscript", "svg", "template", "iframe",
             "object", "canvas", "select", "textarea"}
HEADING_TAGS = {"h1", "h2", "h3", "h4", "h5", "h6"}
BLOCK_TAGS = {"p", "div", "section", "article", "header", "footer", "main",
              "aside", "nav", "ul", "ol", "dl", "dt", "dd", "table", "tr",
              "form", "figure", "figcaption", "address", "details", "summary",
              "fieldset", "center", "caption"}


class TextExtractor(HTMLParser):
    """Convierte HTML en bloques de texto (h, p, li, pre, hr) y enlaces."""

    def __init__(self, page, base_url):
        super().__init__(convert_charrefs=True)
        self.page = page
        self.base = base_url
        self.buf = []
        self.kind = "p"
        self.skip = 0
        self.in_title = False
        self.title_parts = []
        self.in_pre = False
        self.pre_buf = []
        self.href = None
        self.link_start = 0
        self.quote = 0
        self.full = False

    # --- utilidades ---
    def emit(self, kind, text=""):
        if self.full:
            return
        if len(self.page.blocks) >= MAX_BLOCKS:
            self.full = True
            self.page.add("p", "... La página es muy larga y se cortó aquí.")
            return
        self.page.add(kind, text)

    def flush(self):
        text = re.sub(r"\s+", " ", "".join(self.buf)).strip()
        self.buf = []
        self.link_start = 0
        if text:
            if self.quote and self.kind == "p":
                text = "> " + text
            self.emit(self.kind, text)

    def flush_pre(self):
        text = "".join(self.pre_buf).strip("\n")
        self.pre_buf = []
        if text.strip():
            for line in text.split("\n")[:300]:
                self.emit("pre", line.rstrip())

    def resolve(self, href):
        href = (href or "").strip()
        if not href or href.startswith("#"):
            return None
        if href.lower().startswith(("javascript:", "mailto:", "tel:", "data:", "sms:")):
            return None
        absolute = urllib.parse.urljoin(self.base, href)
        absolute, _frag = urllib.parse.urldefrag(absolute)
        if not absolute.lower().startswith(("http://", "https://")):
            return None
        return absolute

    def close_link(self):
        if self.href:
            start = min(self.link_start, len(self.buf))
            text = "".join(self.buf[start:])
            label = re.sub(r"\s+", " ", text).strip()
            if label:
                del self.buf[start:]
                lead = " " if text[:1].isspace() else ""
                trail = " " if text[-1:].isspace() else ""
                self.buf.append(lead + self.page.link(label, self.href) + trail)
        self.href = None

    # --- eventos del parser ---
    def handle_starttag(self, tag, attrs):
        if self.full:
            return
        if tag in SKIP_TAGS:
            self.skip += 1
            return
        if self.skip:
            return
        a = dict(attrs)
        if tag == "title":
            self.in_title = True
        elif tag in HEADING_TAGS:
            self.flush()
            self.kind = "h"
        elif tag == "li":
            self.flush()
            self.kind = "li"
        elif tag == "pre":
            self.flush()
            self.in_pre = True
            self.pre_buf = []
        elif tag == "hr":
            self.flush()
            self.emit("hr")
        elif tag == "br":
            if self.in_pre:
                self.pre_buf.append("\n")
            else:
                self.buf.append(" ")
        elif tag == "blockquote":
            self.flush()
            self.quote += 1
        elif tag == "a":
            self.href = self.resolve(a.get("href"))
            self.link_start = len(self.buf)
        elif tag == "img":
            alt = (a.get("alt") or "").strip()
            if self.href and alt:
                self.buf.append(alt.replace("[", "(").replace("]", ")"))
        elif tag in ("td", "th"):
            self.buf.append(" ")
        elif tag in BLOCK_TAGS:
            self.flush()

    def handle_endtag(self, tag):
        if self.full:
            return
        if tag in SKIP_TAGS:
            if self.skip:
                self.skip -= 1
            return
        if self.skip:
            return
        if tag == "title":
            self.in_title = False
        elif tag in HEADING_TAGS or tag == "li":
            self.flush()
            self.kind = "p"
        elif tag == "pre":
            self.in_pre = False
            self.flush_pre()
        elif tag == "blockquote":
            self.flush()
            self.quote = max(0, self.quote - 1)
        elif tag == "a":
            self.close_link()
        elif tag in BLOCK_TAGS:
            self.flush()

    def handle_data(self, data):
        if self.full or self.skip:
            return
        if self.in_title:
            self.title_parts.append(data)
        elif self.in_pre:
            self.pre_buf.append(data)
        else:
            # Los corchetes del texto original se cambian por paréntesis
            # para que no se confundan con los marcadores [n] de enlaces.
            self.buf.append(data.replace("[", "(").replace("]", ")"))

    def finish(self):
        if self.in_pre:
            self.flush_pre()
        self.flush()
        title = re.sub(r"\s+", " ", "".join(self.title_parts)).strip()
        return title.replace("[", "(").replace("]", ")")


def build_web_page(url, ctype, text, truncated):
    head = text[:1000].lstrip().lower()
    is_html = "html" in ctype or (not ctype and ("<html" in head or head.startswith("<!doctype html")))
    page = Page(url)
    if is_html:
        parser = TextExtractor(page, url)
        try:
            parser.feed(text)
            parser.close()
        except Exception:
            pass  # si el HTML está muy roto se muestra lo que se alcanzó a leer
        title = parser.finish()
        page.title = title or url
        if not page.blocks:
            page.add("p", "(La página no tiene texto que mostrar. Puede que dependa de JavaScript.)")
    elif ctype.startswith("text/") or not ctype or "json" in ctype or "xml" in ctype:
        for line in text.split("\n")[:MAX_BLOCKS - 2]:
            page.add("pre", line.rstrip("\r").expandtabs(4))
    else:
        return error_page(url, f"Tipo de contenido no soportado: {ctype}")
    if truncated:
        page.add("p", f"(La página era muy grande: solo se descargaron los primeros {MAX_BYTES // 1000} KB.)")
    return page


def load_page(url):
    if url.lower().startswith("serpent://"):
        parsed = urllib.parse.urlparse(url)
        if parsed.netloc.lower() == "search":
            query = urllib.parse.parse_qs(parsed.query).get("q", [""])[0]
            return build_search_page(query)
        return build_internal_page(url)
    scheme = urllib.parse.urlparse(url).scheme.lower()
    if scheme not in ("http", "https"):
        return error_page(url, f"Protocolo no soportado: {scheme or 'desconocido'}")
    try:
        final_url, ctype, text, truncated = fetch_url(url)
        return build_web_page(final_url, ctype, text, truncated)
    except urllib.error.HTTPError as e:
        return error_page(url, f"El servidor respondió {e.code} {e.reason}")
    except urllib.error.URLError as e:
        reason = e.reason
        if isinstance(reason, ssl.SSLError) or "CERTIFICATE" in str(reason).upper():
            msg = ("Error de certificado SSL. Si usas Pydroid, cambia "
                   "VERIFY_SSL a False al inicio del script.")
        elif isinstance(reason, socket.timeout):
            msg = "Tiempo de espera agotado. El sitio no respondió a tiempo."
        elif isinstance(reason, socket.gaierror):
            msg = "No se pudo encontrar ese dominio. ¿Tienes Internet?"
        else:
            msg = str(reason)
        return error_page(url, msg)
    except (socket.timeout, TimeoutError):
        return error_page(url, "Tiempo de espera agotado. El sitio no respondió a tiempo.")
    except ssl.SSLError as e:
        return error_page(url, f"Error SSL: {e}")
    except ValueError as e:
        return error_page(url, f"Dirección no válida ({e}).")
    except KeyboardInterrupt:
        return error_page(url, "Carga cancelada.")
    except Exception as e:
        return error_page(url, f"{type(e).__name__}: {e}")


def open_url(url):
    url = normalize_url(url)
    if not url.lower().startswith("serpent://"):
        print(f"{YELLOW}Conectando con {shorten(url, 50)} ...{RESET}")
    return load_page(url)


def refresh_internal(page):
    """Las páginas internas se reconstruyen al volver a ellas (marcadores, historial...)."""
    if page.url.lower().startswith("serpent://") and not page.error:
        parsed = urllib.parse.urlparse(page.url)
        if parsed.netloc.lower() == "search":
            query = urllib.parse.parse_qs(parsed.query).get("q", [""])[0]
            fresh = build_search_page(query)
        else:
            fresh = build_internal_page(page.url)
        fresh.scroll = page.scroll
        return fresh
    return page


def log_visit(page):
    if page.error or page.url in ("serpent://history", "serpent://bookmarks"):
        return
    browser_data["log"].append((datetime.now().strftime("%H:%M"), page.title, page.url))
    del browser_data["log"][:-200]


# ---------------- Dibujo en pantalla ----------------

def term_metrics():
    size = shutil.get_terminal_size((42, 0))
    width = max(30, min(size.columns, 100) - 1)
    rows = max(8, size.lines - 7) if size.lines > 0 else PAGE_ROWS
    return width, rows


def colorize(line, base=""):
    return LINK_RE.sub(lambda m: f"{YELLOW}{m.group(0)}{RESET}{base}", line)


def render_page_lines(page, width):
    out = []
    prev = None
    for kind, text in page.blocks:
        if prev is not None and not (kind == prev and kind in ("li", "pre")):
            out.append("")
        if kind == "h":
            for l in textwrap.wrap(text, width, break_on_hyphens=False) or [""]:
                out.append(f"{BOLD}{CYAN}{colorize(l, BOLD + CYAN)}{RESET}")
        elif kind == "li":
            for l in textwrap.wrap(text, width, initial_indent=" \u2022 ",
                                   subsequent_indent="   ", break_on_hyphens=False) or [""]:
                out.append(colorize(l))
        elif kind == "pre":
            text = text.expandtabs(4)
            for i in range(0, max(len(text), 1), width):
                out.append(f"{GREEN}{text[i:i + width]}{RESET}")
        elif kind == "hr":
            out.append(f"{CYAN}{'-' * width}{RESET}")
        else:
            for l in textwrap.wrap(text, width, break_on_hyphens=False) or [""]:
                out.append(colorize(l))
        prev = kind
    return out


def draw_browser(page, lines, width, rows, notice):
    clear_screen()
    print(f"{CYAN}{'=' * width}{RESET}")
    print(f"{BOLD}{MAGENTA}🐍 SERPENT NET{RESET}")
    print(f"{BOLD}{shorten(page.title, width)}{RESET}")
    print(f"{YELLOW}{shorten(page.url, width)}{RESET}")
    print(f"{CYAN}{'-' * width}{RESET}")
    if page.image_preview and page.scroll == 0:
        print(page.image_preview)
        print(f"{CYAN}{'-' * width}{RESET}")
    window = lines[page.scroll:page.scroll + rows]
    for l in window:
        print(l)
    for _ in range(rows - len(window)):
        print()
    first = page.scroll + 1 if lines else 0
    last = min(page.scroll + rows, len(lines))
    print(f"{CYAN}{'-' * width}{RESET}")
    print(f"Líneas {first}-{last} de {len(lines)} | Enlaces: {len(page.links)}")
    keys = "número:abrir enlace  n/p:pantalla  g:ir  b/f:atrás/adelante  l:enlaces  s:marcar  m:marcadores  h:historial  save:guardar  ?:ayuda  q:salir"
    for l in textwrap.wrap(keys, width):
        print(f"{MAGENTA}{l}{RESET}")
    if notice:
        print(notice)


def show_link_list(page, width, rows):
    if not page.links:
        return f"{YELLOW}Esta página no tiene enlaces.{RESET}"
    print(f"\n{CYAN}--- Enlaces de la página ---{RESET}")
    for i, target in enumerate(page.links, 1):
        print(f"{YELLOW}[{i}]{RESET} {shorten(target, width - 6)}")
        if i % rows == 0 and i < len(page.links):
            input(f"{CYAN}-- Enter para continuar --{RESET}")
    input(f"{CYAN}-- Enter para volver a la página --{RESET}")
    return ""


def save_page_to_disk(page, args):
    """Guarda el texto de la página en un diskette (comando save)."""
    arg = args.strip()
    if arg:
        drive, fname = resolve_path(arg)
    else:
        drive, fname = current_drive, ""
    if ":" in fname:
        return f"{RED}Unidad no válida. Usa a: o b:.{RESET}"
    if not fname:
        fname = (re.sub(r"[^A-Z0-9]", "", page.title.upper())[:8] or "PAGINA") + ".TXT"
    elif "." not in fname:
        fname += ".TXT"

    body = [page.title, page.url, "=" * 40, ""]
    body += [ANSI_RE.sub("", l) for l in render_page_lines(page, 72)]
    if page.links:
        body += ["", "ENLACES", "-------"]
        body += [f"[{i}] {u}" for i, u in enumerate(page.links, 1)]
    text = "\n".join(body)
    size = len(text.encode("utf-8"))

    files = disks_storage[drive]["files"]
    reclaim = 0
    if fname in files:
        ans = input(f"{YELLOW}{fname} ya existe en {drive}:. ¿Sobrescribir? (s/n): {RESET}").strip().lower()
        if ans != "s":
            return f"{YELLOW}Guardado cancelado.{RESET}"
        reclaim = file_size(drive, fname)
    free = disk_free(drive) + reclaim
    if size > free:
        return (f"{RED}No cabe en {drive}:. La página ocupa {fmt_size(size)} y quedan "
                f"{fmt_size(free)}.{RESET}")
    print(f"{YELLOW}* Bzzzt-bzzzt * Grabando en el diskette...{RESET}")
    time.sleep(0.5)
    files[fname] = text
    return f"{GREEN}Página guardada como {drive}:{fname} ({fmt_size(size)}). Léela con: read {drive.lower()}:{fname.lower()}{RESET}"


# ---------------- Bucle del navegador ----------------

def _browser_loop(start):
    width, rows = term_metrics()
    back, fwd = [], []
    current = open_url(start)
    log_visit(current)
    notice = ""

    def go(new_page):
        nonlocal current
        back.append(current)
        del fwd[:]
        current = new_page
        log_visit(current)

    while True:
        lines = render_page_lines(current, width)
        current.scroll = max(0, min(current.scroll, max(0, len(lines) - 1)))
        draw_browser(current, lines, width, rows, notice)
        notice = ""
        try:
            raw = input(f"{CYAN}net>{RESET} ").strip()
        except (KeyboardInterrupt, EOFError):
            print("")
            break
        low = raw.lower()

        if low in ("buscar", "search"):
            try:
                query = input(f"{CYAN}¿Qué querés buscar? {RESET}").strip()
            except (KeyboardInterrupt, EOFError):
                query = ""
            if query:
                go(open_url(query))
            else:
                notice = f"{YELLOW}Búsqueda cancelada.{RESET}"
        elif low.startswith("buscar ") or low.startswith("search "):
            query = raw.split(None, 1)[1].strip()
            if query:
                go(open_url(query))
        elif raw == "" or low == "n":
            if current.scroll + rows < len(lines):
                current.scroll += rows
            else:
                notice = f"{YELLOW}Fin de la página.{RESET}"
        elif low == "p":
            if current.scroll > 0:
                current.scroll = max(0, current.scroll - rows)
            else:
                notice = f"{YELLOW}Ya estás al principio.{RESET}"
        elif low == "t":
            current.scroll = 0
        elif low == "e":
            current.scroll = max(0, len(lines) - rows)
        elif low in ("q", "quit", "exit", "salir"):
            break
        elif low.isdigit():
            n = int(low)
            if 1 <= n <= len(current.links):
                go(open_url(current.links[n - 1]))
            else:
                notice = f"{RED}El enlace {n} no existe en esta página.{RESET}"
        elif low in ("b", "back"):
            if back:
                fwd.append(current)
                current = refresh_internal(back.pop())
            else:
                notice = f"{YELLOW}No hay páginas anteriores.{RESET}"
        elif low in ("f", "fwd"):
            if fwd:
                back.append(current)
                current = refresh_internal(fwd.pop())
            else:
                notice = f"{YELLOW}No hay páginas adelante.{RESET}"
        elif low in ("r", "reload"):
            fresh = open_url(current.url)
            fresh.scroll = current.scroll
            current = fresh
        elif low in ("home", "inicio"):
            go(open_url("serpent://home"))
        elif low == "m":
            go(open_url("serpent://bookmarks"))
        elif low == "h":
            go(open_url("serpent://history"))
        elif low in ("?", "help", "ayuda"):
            go(open_url("serpent://help"))
        elif low == "s":
            if current.error:
                notice = f"{RED}No se puede marcar una página con error.{RESET}"
            elif any(b["url"] == current.url for b in browser_data["bookmarks"]):
                notice = f"{YELLOW}Esta página ya está en tus marcadores.{RESET}"
            else:
                browser_data["bookmarks"].append({"title": current.title, "url": current.url})
                notice = f"{GREEN}Marcador guardado.{RESET}"
        elif low.startswith("x ") and current.url == "serpent://bookmarks":
            arg = low[2:].strip()
            if arg.isdigit() and 1 <= int(arg) <= len(browser_data["bookmarks"]):
                removed = browser_data["bookmarks"].pop(int(arg) - 1)
                current = refresh_internal(current)
                notice = f"{GREEN}Marcador borrado: {shorten(removed['title'], 30)}{RESET}"
            else:
                notice = f"{RED}Número de marcador no válido.{RESET}"
        elif low == "l":
            notice = show_link_list(current, width, rows)
        elif low == "save" or low.startswith("save "):
            notice = save_page_to_disk(current, raw[4:])
        elif low == "g" or low.startswith("g ") or low.startswith("go "):
            target = raw.split(None, 1)[1].strip() if " " in raw else ""
            if not target:
                try:
                    target = input("Dirección o palabras a buscar: ").strip()
                except (KeyboardInterrupt, EOFError):
                    target = ""
            if target:
                go(open_url(target))
        elif re.match(r"^(https?|serpent)://", low) or (" " not in raw and "." in raw):
            go(open_url(raw))
        elif raw:
            go(open_url(raw))
        else:
            notice = f"{RED}Comando no reconocido. Escribe ? para ver la ayuda.{RESET}"


def cmd_browser(args=""):
    start = args.strip() or "serpent://home"
    pid = _spawn_process("SerpentNet")
    try:
        _browser_loop(start)
    finally:
        _end_process(pid)
    print(f"{CYAN}Cerrando Serpent Net... Volviendo a Serpent OS.{RESET}\n")


