def panel(title, width=58):
    print(f"{CYAN}╔" + "═" * (width - 2) + f"╗{RESET}")
    print(f"{CYAN}║{BOLD}{YELLOW}" + title.center(width - 2) + f"{RESET}{CYAN}║{RESET}")
    print(f"{CYAN}╚" + "═" * (width - 2) + f"╝{RESET}")


def typewriter(text, delay=0.015, end="\n"):
    for ch in text:
        sys.stdout.write(ch)
        sys.stdout.flush()
        time.sleep(delay)
    sys.stdout.write(end)
    sys.stdout.flush()


