def _temple_art():
    W = 46
    colors = [YELLOW, YELLOW, WHITE, WHITE, CYAN]
    rows = [("▲".center(W), WHITE)]
    for i, s in enumerate((3, 9, 15, 21, 27)):
        for _ in range(2):
            body = "█" * s
            if i == 4:
                body = "█" * 11 + "▒" * 5 + "█" * 11   # la puerta del templo
            rows.append((body.center(W), colors[i]))
    rows.append((("▀" * 33).center(W), CYAN))
    return rows


def temple_boot():
    clear_screen()
    print()
    for line, color in _temple_art():
        print(f"{color}{line}{RESET}")
        time.sleep(0.07)
    print()
    print(f"{BOLD}{YELLOW}" + "S E R P E N T   O S".center(46) + f"{RESET}")
    print(f"{CYAN}" + "El Templo de la Serpiente - 640x480, 16 colores".center(46) + f"{RESET}\n")
    modulos = [
        "Cargando el Kernel sagrado",
        "Compilando módulos JIT",
        "Montando diskettes A: y B:",
        "Despertando a la serpiente",
    ]
    for i, m in enumerate(modulos, 1):
        time.sleep(0.35)
        bar = "█" * (i * 5) + "░" * ((len(modulos) - i) * 5)
        print(f" {WHITE}[{GREEN}{bar}{WHITE}]{RESET} {m:<28} {GREEN}OK{RESET}")
    time.sleep(0.6)


def cmd_oracle():
    panel("EL ORÁCULO DE LA SERPIENTE")
    print(f"{WHITE}Concentra tu pregunta en silencio y pulsa {MAGENTA}ENTER{WHITE} para recibir palabras.{RESET}")
    try:
        input()
    except (EOFError, KeyboardInterrupt):
        print()
        return
    words = random.sample(ORACLE_WORDS, random.randint(8, 12))
    print(f"{CYAN}El Oráculo dice:{RESET}\n")
    colors = [YELLOW, WHITE, CYAN, GREEN, MAGENTA]
    try:
        for i, w in enumerate(words):
            sys.stdout.write(f"  {BOLD}{colors[i % len(colors)]}{w}{RESET}")
            sys.stdout.flush()
            time.sleep(0.45)
            if i % 4 == 3:
                sys.stdout.write("\n")
    except KeyboardInterrupt:
        pass
    print("\n")
    try:
        vision = input(f"{WHITE}¿Qué visión ves en estas palabras? (ENTER para omitir): {RESET}").strip()
    except (EOFError, KeyboardInterrupt):
        print()
        return
    if not vision:
        print(f"{YELLOW}El Oráculo guarda silencio.{RESET}\n")
        return
    text = "Palabras: " + " ".join(words) + "\n" + vision
    files = disks_storage[current_drive]["files"]
    n = 1
    while f"VISION{n}.TXT" in files:
        n += 1
    name = f"VISION{n}.TXT"
    if len(text.encode("utf-8")) <= disk_free(current_drive):
        files[name] = text
        print(f"{GREEN}Visión guardada en {current_drive}:\\{name}. Léela con 'read {name.lower()}'.{RESET}\n")
    else:
        print(f"{RED}No hay espacio en el diskette {current_drive}: para guardar tu visión.{RESET}\n")


