# ---------------- SERPENT EVENTS ----------------
def serpent_event(message, level="info", source="system"):
    """Registra un evento local y persistente del entorno Serpent OS."""
    try:
        events = system_state.setdefault("events", [])
        if not isinstance(events, list):
            events = []
            system_state["events"] = events
        events.append({
            "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "level": str(level).lower()[:8],
            "source": str(source)[:24],
            "message": str(message)[:180],
        })
        del events[:-150]
    except Exception:
        pass


def cmd_events(args=""):
    """Consulta el registro local de eventos de Serpent OS."""
    parts = args.split()
    action = parts[0].lower() if parts else "list"
    events = system_state.setdefault("events", [])
    if action in ("clear", "clean", "flush"):
        try:
            answer = input("¿Borrar el historial de eventos? (s/N): ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            print("\nCancelado.")
            return
        if answer in ("s", "si", "sí", "y", "yes"):
            events.clear()
            serpent_event("Historial de eventos reiniciado", "warn", "events")
            save_system()
            print(f"{GREEN}Historial limpiado.{RESET}")
        else:
            print(f"{YELLOW}No se modificó el historial.{RESET}")
        return
    if action in ("help", "-h", "--help"):
        print("Uso: events [list|recent [N]|info|clear]")
        print("  list       Muestra los últimos 25 eventos")
        print("  recent N   Muestra los últimos N eventos (máximo 150)")
        print("  info       Resumen por nivel")
        print("  clear      Borra el historial con confirmación")
        return
    if action == "info":
        counts = {"info": 0, "warn": 0, "error": 0}
        for event in events:
            level = event.get("level", "info")
            counts[level] = counts.get(level, 0) + 1
        panel("SERPENT EVENTS · RESUMEN")
        print(f"  Eventos guardados: {len(events)} / 150")
        print(f"  {GREEN}INFO: {counts.get('info', 0)}{RESET}   {YELLOW}WARN: {counts.get('warn', 0)}{RESET}   {RED}ERROR: {counts.get('error', 0)}{RESET}")
        return
    if action not in ("list", "recent"):
        print("Uso: events [list|recent [N]|info|clear]")
        return
    amount = 25
    if len(parts) > 1:
        try:
            amount = max(1, min(150, int(parts[1])))
        except ValueError:
            print("La cantidad debe ser un número entre 1 y 150.")
            return
    panel("SERPENT EVENTS · REGISTRO DEL SISTEMA")
    if not events:
        print("  No hay eventos registrados todavía.")
        return
    print(f"  {'FECHA Y HORA':<20} {'NIVEL':<7} {'ORIGEN':<13} EVENTO")
    print("  " + "─" * 76)
    colors = {"info": GREEN, "warn": YELLOW, "error": RED}
    for event in events[-amount:]:
        level = event.get("level", "info")
        color = colors.get(level, WHITE)
        stamp = event.get("time", "-")
        source = event.get("source", "system")
        message = event.get("message", "")
        print(f"  {stamp:<20} {color}{level.upper():<7}{RESET} {source:<13} {message}")
    print(f"\n  Mostrando {min(amount, len(events))} de {len(events)} eventos. Máximo guardado: 150.")


