# ---------------- Temas ----------------

def apply_theme(name):
    global THEME, RESET, CYAN, GREEN, YELLOW, RED, MAGENTA, WHITE, _HOVER
    if name not in THEMES:
        return False
    THEME = THEMES[name]
    RESET = "\033[0m" + THEME
    accents = THEME_ACCENTS.get(name, ("36", "32", "33", "31", "35", "37"))
    CYAN, GREEN, YELLOW, RED, MAGENTA, WHITE = (
        f"\033[{code}m" for code in accents
    )
    # El resaltado del ratón acompaña el color principal del tema.
    hover_bg = {"templo": "106", "terminal": "46", "matrix": "102",
                "ambar": "103", "dos": "47", "oceano": "106",
                "medianoche": "104", "bosque": "102", "rubi": "101",
                "violeta": "105", "indigo": "104", "carbon": "47",
                "pizarra": "107", "borgona": "101", "petroleo": "106",
                "ciruela": "105", "obsidiana": "105", "terminal-azul": "104",
                "terminal-rojo": "101", "amber-crt": "103", "papel": "47",
                "hueso": "47", "vga-amarillo": "103", "glaciar": "106",
                "aurora": "102", "cometa": "104"}.get(name, "106")
    _HOVER = f"\033[0;30;{hover_bg}m\033[1m"
    system_state["theme"] = name
    # Guarda el tema en cuanto se aplica, sin esperar al siguiente comando
    # ni a la secuencia de apagado. Así sobrevive al cierre de la terminal.
    save_system()
    return True


# ---------------- Persistencia ----------------

def save_system():
    """Guarda diskettes, ajustes y datos en un JSON junto al script."""
    state = {k: system_state[k] for k in PERSIST_KEYS}
    state["history"] = state["history"][-100:]
    state["trash"] = state["trash"][-50:]
    data = {
        "disks": {d: info["files"] for d, info in disks_storage.items()},
        "state": state,
        "rpg": rpg_stats,
        "bookmarks": browser_data["bookmarks"],
        "packages": dict(SERPENT_INSTALLED_PACKAGES),
    }
    try:
        tmp = SAVE_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        # Conserva la última partida válida antes de sustituir el archivo principal.
        if os.path.isfile(SAVE_FILE):
            try:
                with open(SAVE_FILE, "r", encoding="utf-8") as previous:
                    json.load(previous)
                shutil.copy2(SAVE_FILE, SAVE_FILE + ".bak")
            except (OSError, ValueError, TypeError):
                pass
        os.replace(tmp, SAVE_FILE)
        return True
    except (OSError, TypeError, ValueError):
        return False


def load_system():
    data = None
    try:
        with open(SAVE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError, TypeError):
        # Si el archivo principal se dañó, intenta recuperar la última copia válida.
        try:
            with open(SAVE_FILE + ".bak", "r", encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError, TypeError):
            return False
    if not isinstance(data, dict):
        return False
    saved_disks = data.get("disks")
    if isinstance(saved_disks, dict):
        for d, files in saved_disks.items():
            if d in disks_storage and isinstance(files, dict):
                disks_storage[d]["files"] = {
                    str(k): v for k, v in files.items()
                    if isinstance(k, (str, int)) and isinstance(v, str)
                }
    leeme = disks_storage["A"]["files"].get("LEEME.TXT")
    if leeme:   # actualiza la versión en partidas guardadas con una versión anterior
        disks_storage["A"]["files"]["LEEME.TXT"] = re.sub(
            r"(Serpent OS v)\d+\.\d+\.\d+", lambda m: m.group(1) + OS_VERSION, leeme)
    state = data.get("state")
    if not isinstance(state, dict):
        state = {}
    for k in PERSIST_KEYS:
        if k in state and type(state[k]) is type(system_state[k]):
            system_state[k] = state[k]
    rpg = data.get("rpg")
    if isinstance(rpg, dict):
        for k, v in rpg.items():
            if k in rpg_stats and isinstance(v, int):
                rpg_stats[k] = v
    packages = data.get("packages")
    if isinstance(packages, dict):
        SERPENT_INSTALLED_PACKAGES.clear()
        for name, version in packages.items():
            if name in SERPENT_PACKAGE_REPO and isinstance(version, str):
                SERPENT_INSTALLED_PACKAGES[name] = version
    bms = data.get("bookmarks")
    if isinstance(bms, list):
        browser_data["bookmarks"][:] = [
            b for b in bms
            if isinstance(b, dict) and isinstance(b.get("url"), str) and b["url"].strip()
        ]
    if not isinstance(system_state.get("events"), list):
        system_state["events"] = []
    system_state["events"] = [e for e in system_state["events"][-150:] if isinstance(e, dict)]
    apply_theme(system_state["theme"])
    return True


def reset_runtime():
    """Estado de RAM: se limpia en cada arranque (los diskettes se cargan aparte)."""
    global current_drive
    current_drive = "A"
    active_processes[:] = [dict(p) for p in DEFAULT_PROCESSES]
    KERNEL.reset()


