def cmd_dashboard(args=""):
    """Panel clásico de estado general; solo consulta subsistemas virtuales."""
    width = max(34, min(58, _term_cols() or 58))
    services = globals().get("SERPENT_SERVICES", {})
    packages = globals().get("SERPENT_INSTALLED_PACKAGES", {})

    def draw():
        clear_screen()
        panel("SERPENT OS · DASHBOARD", width)
        print(f"  {YELLOW}Serpent OS {OS_VERSION}{RESET}   "
              f"{CYAN}{system_state.get('user', 'user')}@{system_state.get('hostname', 'serpent')}{RESET}")
        print(f"  Kernel: {KERNEL.NAME} {KERNEL.VERSION}   "
              f"Unidad actual: {current_drive}:")
        print("")

        # Estado general
        total, used, free = KERNEL.mem_stats()
        used_mb = used * KERNEL.PAGE_KB / 1024
        total_mb = total * KERNEL.PAGE_KB / 1024
        mem_ratio = (used / total) if total else 0
        print(f"  {BOLD}{CYAN}ESTADO DEL SISTEMA{RESET}")
        print(f"  Procesos virtuales : {len(active_processes)}")
        print(f"  Memoria virtual    : {_bar(mem_ratio, 14)} "
              f"{used_mb:.1f}/{total_mb:.1f} MB")
        print(f"  Tiempo activo      : {_fmt_uptime(time.time() - BOOT_TIME)}")
        print("")

        # Unidades virtuales
        print(f"  {BOLD}{CYAN}UNIDADES{RESET}")
        for drive, info in disks_storage.items():
            capacity = DISK_CAPACITY.get(drive, 0)
            occupied = disk_used(drive)
            ratio = occupied / capacity if capacity else 0
            marker = f"{GREEN}*{RESET}" if drive == current_drive else " "
            print(f"  {marker} {drive}: {info.get('label', 'UNIDAD')[:18]:<18} "
                  f"{_bar(ratio, 10)} {fmt_size(occupied)}/{fmt_size(capacity)}")
        print("")

        # Servicios del init virtual
        print(f"  {BOLD}{CYAN}SERVICIOS{RESET}")
        if services:
            active = [name for name, svc in services.items()
                      if svc.get("state") == "active"]
            failed = [name for name, svc in services.items()
                      if svc.get("state") == "failed"]
            print(f"  Activos: {len(active)}/{len(services)}   "
                  f"Fallidos: {len(failed)}")
            shown = list(services.items())[:5]
            for name, svc in shown:
                state = svc.get("state", "unknown")
                color = GREEN if state == "active" else RED if state == "failed" else YELLOW
                print(f"  {name:<17} {color}{state.upper():<10}{RESET}")
            if len(services) > len(shown):
                print(f"  ... y {len(services) - len(shown)} servicios más "
                      f"(systemctl list)")
        else:
            print("  Gestor de servicios no disponible.")
        print("")

        # Extensiones instaladas
        print(f"  {BOLD}{CYAN}EXTENSIONES{RESET}")
        print(f"  Paquetes instalados: {len(packages)}/"
              f"{len(globals().get('SERPENT_PACKAGE_REPO', {})) or 50}")
        print("")

        # Red virtual
        network = services.get("network", {})
        net_state = network.get("state", "no disponible")
        net_color = GREEN if net_state == "active" else YELLOW if net_state == "inactive" else RED
        print(f"  {BOLD}{CYAN}RED{RESET}")
        print(f"  Servicio de red virtual: {net_color}{net_state.upper()}{RESET}")
        print("")
        print(f"  {CYAN}[R]{RESET} Actualizar    "
              f"{CYAN}[Q]{RESET} Volver a la terminal")

    try:
        while True:
            draw()
            try:
                action = input(f"\n{GREEN}dashboard>{RESET} ").strip().lower()
            except (EOFError, KeyboardInterrupt):
                print("")
                return
            if action in ("q", "quit", "salir", "exit", ""):
                clear_screen()
                print(f"{GREEN}Volviste a la terminal de Serpent OS.{RESET}")
                return
            if action in ("r", "refresh", "actualizar"):
                continue
            print(f"{YELLOW}Opción no válida. Usa R para actualizar o Q para salir.{RESET}")
            time.sleep(1)
    except KeyboardInterrupt:
        print("")
        return



def _top_loop(secs):
    clear_screen()
    end = time.time() + secs
    try:
        while time.time() < end:
            KERNEL.tick()
            total_cpu = min(100.0, sum(float(p["cpu"].rstrip("%")) for p in active_processes))
            used, total = _mem_usage()
            lines = _panel_lines("MONITOR DE RECURSOS")
            lines += [f"  {CYAN}CPU    {RESET}{_bar(total_cpu / 100, 30)} {total_cpu:5.1f}%",
                      f"  {CYAN}Memoria{RESET}{_bar(used / total, 30)} {used}/{total} MB",
                      f"  {CYAN}Uptime {RESET}{_fmt_uptime(time.time() - BOOT_TIME)}   "
                      f"{CYAN}Procesos{RESET} {len(active_processes)}", ""]
            lines.append(f"  {CYAN}Carga  {RESET} {KERNEL.loadavg[0]:.2f} {KERNEL.loadavg[1]:.2f} {KERNEL.loadavg[2]:.2f}")
            lines.append(f"{BOLD}{'  PID':<7}{'NOMBRE':<16}{'ESTADO':<10}CPU{RESET}")
            for p in active_processes[:14]:
                frac = float(p["cpu"].rstrip("%")) / 100
                lines.append(f"  {p['pid']:<5}{MAGENTA}{p['name']:<16}{RESET}{YELLOW}{p['status']:<10}{RESET}"
                             f"{_bar(frac * 4, 12)} {p['cpu']}")
            lines += ["", f"{WHITE}  (Ctrl+C para salir | se cierra solo en {max(0, int(end - time.time()))}s){RESET}"]
            _frame(lines)
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    print("")


def cmd_top(args):
    run_app("top", _top_loop, _int_arg(args, 30, 1, 600))


def cmd_uptime(args=""):
    print(f"{YELLOW}Encendido hace {_fmt_uptime(time.time() - BOOT_TIME)}  |  "
          f"{len(active_processes)} procesos  |  {datetime.now().strftime('%H:%M:%S')}{RESET}")


def cmd_ver(args=""):
    print(f"{YELLOW}Serpent OS v{OS_VERSION}{RESET} - kernel {KERNEL.NAME} {KERNEL.VERSION} - Python {platform.python_version()}")


# ---------------- Red ----------------

def _local_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.settimeout(1)
        s.connect(("8.8.8.8", 80))     # no envía datos, solo elige la interfaz
        ip = s.getsockname()[0]
        s.close()
        return ip
    except OSError:
        return None


def _tcp_ping(host, port, timeout=3):
    t0 = time.time()
    try:
        with socket.create_connection((host, port), timeout=timeout):
            pass
        return (time.time() - t0) * 1000
    except (OSError, UnicodeError):
        return None


def cmd_net(args=""):
    panel("RED - SERPENT_MODEM_56K (COM1)")
    online = _tcp_ping("1.1.1.1", 53, 2) is not None
    print(f"  {CYAN}Equipo      :{RESET} {system_state['hostname']}")
    print(f"  {CYAN}Internet    :{RESET} {GREEN + 'CONECTADO' if online else RED + 'SIN SEÑAL'}{RESET}\n")


def cmd_ping(args):
    host = args.strip() or "example.com"
    host = re.sub(r"^https?://", "", host).split("/")[0]
    port = 443
    if ":" in host:
        host, _, p = host.rpartition(":")
        if not p.isdigit():
            print(f"{RED}Puerto no válido.{RESET}")
            return
        port = int(p)
    print(f"{CYAN}PING {host}:{port} (conexión TCP){RESET}")
    times = []
    for _ in range(4):
        ms = _tcp_ping(host, port)
        if ms is None:
            print(f"  {RED}sin respuesta de {host}{RESET}")
        else:
            times.append(ms)
            print(f"  {GREEN}respuesta de {host}: tiempo={ms:.0f} ms{RESET}")
        time.sleep(0.4)
    if times:
        print(f"{YELLOW}{len(times)}/4 recibidos | mín {min(times):.0f} ms | "
              f"media {sum(times) / len(times):.0f} ms | máx {max(times):.0f} ms{RESET}")
    else:
        print(f"{RED}0/4 recibidos. Revisa tu conexión o el nombre del servidor.{RESET}")


# ---------------- Ajustes, temas, seguridad ----------------

def cmd_theme(args):
    name = args.strip().lower()
    if name in THEMES:
        apply_theme(name)
        clear_screen()
        print(f"{GREEN}Tema '{name}' aplicado.{RESET}")
        return
    if name:
        print(f"{RED}Tema desconocido: '{name}'.{RESET}")
    print(f"{CYAN}Temas disponibles (actual: {system_state['theme']}):{RESET}")
    for n, code in THEMES.items():
        print(f"  {code}  {n:<9} Aa Bb Cc 123  {RESET}")
    print(f"{YELLOW}Usa: theme nombre{RESET}")


def cmd_passwd(args=""):
    old = _ask(f"{CYAN}Contraseña actual: {RESET}")
    if old is None:
        return
    if old.strip() != system_state["password"]:
        print(f"{RED}Contraseña incorrecta.{RESET}")
        return
    new = _ask(f"{CYAN}Nueva contraseña: {RESET}")
    if new is None:
        return
    new = new.strip()
    if len(new) < 3:
        print(f"{RED}Debe tener al menos 3 caracteres.{RESET}")
        return
    again = _ask(f"{CYAN}Repite la nueva contraseña: {RESET}")
    if again is None:
        return
    if again.strip() != new:
        print(f"{RED}Las contraseñas no coinciden.{RESET}")
        return
    system_state["password"] = new
    print(f"{GREEN}Contraseña actualizada.{RESET}")


def cmd_hostname(args):
    name = args.strip().lower()
    if not name:
        print(f"{YELLOW}{system_state['hostname']}{RESET}")
    elif re.fullmatch(r"[a-z0-9-]{1,16}", name):
        system_state["hostname"] = name
        print(f"{GREEN}Nombre del equipo: {name}{RESET}")
    else:
        print(f"{RED}Usa 1-16 caracteres: letras minúsculas, números o guiones.{RESET}")


def cmd_lock(args=""):
    clear_screen()
    panel("PANTALLA BLOQUEADA")
    print(f"\n{YELLOW}" + datetime.now().strftime("%H:%M").center(58) + f"{RESET}")
    print(f"{CYAN}" + f"Sesión de {system_state['user']} bloqueada".center(58) + f"{RESET}\n")
    while True:
        try:
            pw = input(f"{CYAN}Contraseña: {RESET}").strip()
        except KeyboardInterrupt:
            print()
            continue
        except EOFError:
            return
        if pw == system_state["password"]:
            break
        print(f"{RED}Contraseña incorrecta.{RESET}")
        time.sleep(1)
    clear_screen()
    print(f"{GREEN}Sesión desbloqueada. Bienvenido de nuevo, {system_state['user']}.{RESET}")


def cmd_factory_reset():
    conf = _ask(f"{RED}Esto borra TODOS los archivos y ajustes. Escribe BORRAR para confirmar: {RESET}")
    if conf is None or conf.strip() != "BORRAR":
        print(f"{YELLOW}Operación cancelada.{RESET}")
        return
    for d in disks_storage:
        disks_storage[d]["files"] = dict(DEFAULT_DISK_FILES[d])
    rpg_stats.update(DEFAULT_RPG)
    browser_data["bookmarks"].clear()
    browser_data["log"].clear()
    system_state.update(password="1234", hostname="serpent", aliases={}, todos=[],
                        contacts={}, history=[], trash=[], mail=new_mail_state(),
                        campaign=new_campaign_state(), env={})
    apply_theme(DEFAULT_THEME)
    save_system()
    clear_screen()
    print(f"{GREEN}Sistema restaurado a los valores de fábrica.{RESET}")


def cmd_settings(args=""):
    while True:
        panel("AJUSTES DEL SISTEMA")
        print(f"  {MAGENTA}1{RESET}) Tema de color         [{YELLOW}{system_state['theme']}{RESET}]")
        print(f"  {MAGENTA}2{RESET}) Cambiar contraseña")
        print(f"  {MAGENTA}3{RESET}) Nombre del equipo     [{YELLOW}{system_state['hostname']}{RESET}]")
        print(f"  {MAGENTA}4{RESET}) Guardar ahora")
        print(f"  {MAGENTA}5{RESET}) Restaurar valores de fábrica")
        print(f"  {MAGENTA}0{RESET}) Volver")
        choice = _ask(f"{CYAN}Opción: {RESET}")
        if choice is None or choice.strip() in ("0", ""):
            return
        choice = choice.strip()
        if choice == "1":
            cmd_theme("")
            name = _ask(f"{CYAN}Nombre del tema (ENTER para cancelar): {RESET}")
            if name and name.strip():
                cmd_theme(name)
        elif choice == "2":
            cmd_passwd()
        elif choice == "3":
            name = _ask(f"{CYAN}Nuevo nombre del equipo: {RESET}")
            if name is not None:
                cmd_hostname(name)
        elif choice == "4":
            cmd_sync()
        elif choice == "5":
            cmd_factory_reset()
        else:
            print(f"{RED}Opción no válida.{RESET}")
        print("")


# ---------------- Alias e historial ----------------

def cmd_alias(args):
    aliases = system_state["aliases"]
    if not args.strip():
        if not aliases:
            print(f"{YELLOW}No hay alias. Crea uno: alias ll=dir{RESET}")
        for k, v in sorted(aliases.items()):
            print(f"  {MAGENTA}{k:<10}{RESET} = {YELLOW}{v}{RESET}")
        return
    if "=" not in args:
        print(f"{RED}Uso: alias nombre=comando   (ej. alias ll=dir b:){RESET}")
        return
    name, _, target = args.partition("=")
    name, target = name.strip().lower(), target.strip()
    if not re.fullmatch(r"[a-z0-9_!?.-]+", name) or not target:
        print(f"{RED}Alias no válido.{RESET}")
        return
    aliases[name] = target
    print(f"{GREEN}Alias creado: {name} -> {target}{RESET}")


def cmd_unalias(args):
    name = args.strip().lower()
    if system_state["aliases"].pop(name, None) is None:
        print(f"{RED}No existe el alias '{name}'.{RESET}")
    else:
        print(f"{GREEN}Alias '{name}' eliminado.{RESET}")


def cmd_history(args):
    h = system_state["history"]
    if args.strip().lower() == "clear":
        h.clear()
        print(f"{GREEN}Historial borrado.{RESET}")
        return
    n = _int_arg(args, 20, 1, 200)
    start = max(0, len(h) - n)
    for i in range(start, len(h)):
        print(f"  {CYAN}{i + 1:>4}{RESET}  {h[i]}")
    if not h:
        print(f"{YELLOW}(historial vacío){RESET}")


def expand_history(line):
    h = system_state["history"]
    if line == "!!" and h:
        return h[-1]
    if line[1:].isdigit() and 1 <= int(line[1:]) <= len(h):
        return h[int(line[1:]) - 1]
    print(f"{RED}Historial: ningún comando coincide con '{line}'.{RESET}")
    return None


