# Sinónimos -> comando principal (todo sin tildes)
MAN_ALIASES = {
    "manual": "man", "cls": "clear", "ls": "dir", "type": "read", "cat": "read",
    "cp": "copy", "mv": "move", "ren": "move", "rm": "del", "erase": "del",
    "grep": "find", "about": "templo", "god": "oraculo", "sysinfo": "neofetch",
    "version": "ver", "config": "settings", "correo": "mail", "restart": "reboot",
}

# Orden y secciones del índice (las mismas que en 'help')
MAN_GROUPS = [
    ("SISTEMA", ["help", "man", "clear", "date", "whoami", "ps", "kill", "exit", "reboot"]),
    ("DISKETTES", ["disk", "mount", "dir", "edit", "read", "format"]),
    ("INTERNET Y JUEGOS", ["browser", "store", "apps", "games", "run", "rpg", "shop", "matrix"]),
    ("TEMPLO", ["oraculo", "himno", "templo"]),
    ("ARCHIVOS", ["copy", "move", "del", "trash", "echo", "find", "stat", "tree", "hex"]),
    ("APLICACIONES", ["calc", "conv", "cal", "clock", "timer", "crono", "todo", "agenda",
                      "mail", "genpass"]),
    ("SISTEMA AVANZADO", ["top", "neofetch", "uptime", "ver", "net", "ping", "settings", "theme",
                          "passwd", "hostname", "alias", "unalias", "history", "lock", "sync"]),
]


def _man_norm(text):
    """Minúsculas y sin tildes, para que 'ORÁCULO' y 'oraculo' sean lo mismo."""
    text = unicodedata.normalize("NFD", text.strip().lower())
    return "".join(c for c in text if not unicodedata.combining(c))


def _man_width():
    cols = _term_cols() or 58
    return max(30, min(58, cols - 1))


def _man_index():
    panel("MANUAL DE SERPENT OS")
    print(f"  {WHITE}Escribe {MAGENTA}man comando{WHITE} para ver qué hace y sus secretos.")
    print(f"  Ejemplos: {MAGENTA}man kill{WHITE}, {MAGENTA}man games{WHITE}, {MAGENTA}man alias{RESET}\n")
    width = _man_width()
    for titulo, nombres in MAN_GROUPS:
        print(f"{CYAN}══ {YELLOW}{titulo}{CYAN} " + "═" * max(0, 52 - len(titulo)) + f"{RESET}")
        line, size = "  ", 2
        for n in nombres:
            if size + len(n) + 2 > width and size > 2:
                print(line)
                line, size = "  ", 2
            line += f"{MAGENTA}{n}{RESET}  "
            size += len(n) + 2
        if size > 2:
            print(line)
    print("")


def _man_wrap(text, bullet=None):
    width = _man_width()
    if bullet:
        lines = textwrap.wrap(text, width=width, initial_indent="    " + bullet + " ",
                              subsequent_indent="      ",
                              break_on_hyphens=False)
        if lines:
            lines[0] = lines[0].replace(bullet, f"{YELLOW}{bullet}{RESET}", 1)
        return lines
    return textwrap.wrap(text, width=width, initial_indent="    ", subsequent_indent="    ",
                         break_on_hyphens=False)


def cmd_man(args):
    parts = args.split()
    if not parts:
        _man_index()
        return
    name = _man_norm(parts[0])
    shown = parts[0]
    # Si es un alias del usuario (y no un comando conocido), mostramos el manual de su destino
    user_aliases = system_state["aliases"]
    if name in user_aliases and name not in MAN_PAGES and name not in MAN_ALIASES:
        target = user_aliases[name].split()
        print(f"{YELLOW}'{name}' es tu alias de '{user_aliases[name]}'.{RESET}")
        if target:
            name = _man_norm(target[0])
    key = MAN_ALIASES.get(name, name)
    page = MAN_PAGES.get(key)
    if page is None:
        print(f"{RED}No hay manual para '{shown}'. Escribe 'man' para ver la lista.{RESET}")
        close = difflib.get_close_matches(name, list(MAN_PAGES) + list(MAN_ALIASES), n=3, cutoff=0.6)
        if close:
            print(f"{YELLOW}¿Quisiste decir: {', '.join(close)}?{RESET}")
        return
    uso, que, secretos, ver = page
    panel(f"MANUAL: {key}")
    print(f"{CYAN}  QUÉ HACE{RESET}")
    for ln in _man_wrap(que):
        print(ln)
    print(f"{CYAN}  USO{RESET}")
    for ln in _man_wrap(uso):
        print(f"{MAGENTA}{ln}{RESET}")
    print(f"{CYAN}  SECRETOS{RESET}")
    for s in secretos:
        for ln in _man_wrap(s, "◆"):
            print(ln)
    if ver:
        print(f"{CYAN}  VER TAMBIÉN{RESET}  " + ", ".join(f"{MAGENTA}{v}{RESET}" for v in ver))
    print("")




def cmd_explorer(args=""):
    """Explorador clásico de archivos para las unidades virtuales A:, B: y C:."""
    drive = current_drive
    filtro = ""
    while True:
        files = disks_storage[drive]["files"]
        names = sorted(
            [n for n in files if filtro.casefold() in n.casefold()],
            key=str.casefold
        )
        clear_screen()
        panel("SERPENT EXPLORER", 62)
        print(f"  {CYAN}Unidad:{RESET} {YELLOW}{drive}:/{RESET}  "
              f"{CYAN}Etiqueta:{RESET} {disks_storage[drive].get('label', 'DISK')}")
        print(f"  {CYAN}Elementos:{RESET} {len(names)}"
              f"  {CYAN}Ocupado:{RESET} {fmt_size(disk_used(drive))}"
              f"  {CYAN}Libre:{RESET} {fmt_size(disk_free(drive))}")
        print("  " + "─" * 58)
        if filtro:
            print(f"  Filtro: {YELLOW}{filtro}{RESET}")
        if not names:
            print(f"  {YELLOW}(No hay archivos que mostrar){RESET}")
        else:
            print(f"  {CYAN}{'#':>3}  {'NOMBRE':<30} {'TIPO':<8} {'TAMAÑO':>10}{RESET}")
            for i, name in enumerate(names, 1):
                content = files.get(name, "")
                ext = name.rsplit(".", 1)[-1].upper() if "." in name else "FILE"
                kind = "JUEGO" if is_game_file(content) else ext[:8]
                size = file_size(drive, name)
                print(f"  {YELLOW}{i:>3}{RESET}  {WHITE}{name[:30]:<30}{RESET} "
                      f"{MAGENTA}{kind:<8}{RESET} {size:>8} B")
        print("  " + "─" * 58)
        print(f"  {GREEN}O{RESET} abrir  {GREEN}E{RESET} editar/crear  "
              f"{GREEN}D{RESET} borrar  {GREEN}C{RESET} cambiar unidad")
        print(f"  {GREEN}S{RESET} buscar  {GREEN}A{RESET} mostrar todo  "
              f"{GREEN}R{RESET} actualizar  {GREEN}Q{RESET} salir")
        try:
            choice = input(f"\n{CYAN}explorer:{drive}> {RESET}").strip()
        except (EOFError, KeyboardInterrupt):
            print()
            return
        if not choice:
            continue
        op = choice.split(maxsplit=1)
        action = op[0].lower()
        arg = op[1].strip() if len(op) > 1 else ""

        if action in ("q", "quit", "exit", "salir"):
            return
        elif action in ("r", "refresh", "actualizar"):
            continue
        elif action in ("a", "all", "todo"):
            filtro = ""
        elif action in ("s", "search", "buscar"):
            if arg:
                filtro = arg
            else:
                try:
                    filtro = input("Nombre a buscar (vacío = cancelar): ").strip()
                except (EOFError, KeyboardInterrupt):
                    filtro = ""
        elif action in ("c", "cd", "drive", "unidad"):
            target = (arg or input("Unidad (A/B/C): ")).strip().upper().rstrip(":")
            if target in disks_storage:
                drive = target
                filtro = ""
            else:
                print(f"{RED}Unidad no válida. Usa A, B o C.{RESET}")
                input("Enter para continuar...")
        elif action in ("o", "open", "abrir", "e", "edit", "editar", "d", "del", "delete", "borrar"):
            try:
                index_text = arg or input("Número del archivo: ").strip()
                index = int(index_text)
                if not 1 <= index <= len(names):
                    raise ValueError
                filename = names[index - 1]
            except (ValueError, EOFError, KeyboardInterrupt):
                print(f"{RED}Número de archivo no válido.{RESET}")
                input("Enter para continuar...")
                continue
            if action in ("o", "open", "abrir"):
                clear_screen()
                panel(f"ARCHIVO  {drive}:/{filename}", 62)
                cmd_read(f"{drive}:{filename}")
                input(f"\n{CYAN}Enter para volver al explorador...{RESET}")
            elif action in ("e", "edit", "editar"):
                cmd_edit(f"{drive}:{filename}")
            else:
                confirm = input(f"¿Enviar {filename} a la papelera? (s/N): ").strip().lower()
                if confirm in ("s", "si", "sí", "y", "yes"):
                    cmd_del(f"{drive}:{filename}")
                    input("Enter para continuar...")
        elif action in ("new", "nuevo", "crear", "n"):
            filename = arg or input("Nombre del nuevo archivo: ").strip()
            if filename:
                cmd_edit(f"{drive}:{filename}")
        else:
            print(f"{YELLOW}Comando desconocido. Usa O, E, D, C, S, A o Q.{RESET}")
            input("Enter para continuar...")



