_ANSI_ALL_RE = re.compile(r"\x1b\[[0-9;?]*[@-~]")
_VAR_RE = re.compile(r"%([A-Za-z_][A-Za-z0-9_]*)%|\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)")
