# ---------------- Protector de pantalla ----------------

def _saver_tecla_enter():
    """True si el usuario presionó Enter mientras corre el protector."""
    try:
        if os.name == "nt":
            import msvcrt
            if msvcrt.kbhit():
                return msvcrt.getch() in (b"\r", b"\n")
            return False
        import select
        if select.select([sys.stdin], [], [], 0)[0]:
            sys.stdin.read(1)
            return True
    except Exception:
        pass
    return False


def _saver_draw(grid):
    _frame(["".join(r) for r in grid] + [f"{WHITE}  (Enter o Ctrl+C para salir){RESET}"])


def _saver_loop(mode, secs):
    w = max(20, min((_term_cols() or 60) - 1, 100))
    h = max(8, min((_term_rows() or 20) - 3, 40))
    end = time.time() + secs
    clear_screen()
    sys.stdout.write("\033[?25l")           # oculta el cursor
    try:
        if mode == "lluvia":
            charset = "01ABCDEFXYZ#$*+"

            def new_drop():
                return [random.randint(-h, 0), random.randint(4, 10), random.choice((1, 1, 2))]
            drops = [new_drop() for _ in range(w)]
            for d in drops:
                d[0] = random.randint(-h, h)
            while time.time() < end and not _saver_tecla_enter():
                grid = [[" "] * w for _ in range(h)]
                for x, d in enumerate(drops):
                    for k in range(d[1]):
                        y = d[0] - k
                        if 0 <= y < h:
                            col = WHITE if k == 0 else (GREEN if k < d[1] // 2 else CYAN)
                            grid[y][x] = f"{col}{random.choice(charset)}{RESET}"
                    d[0] += d[2]
                    if d[0] - d[1] > h:
                        d[:] = new_drop()
                _saver_draw(grid)
                time.sleep(0.07)
        elif mode == "estrellas":
            def new_star():
                return [random.uniform(-1, 1), random.uniform(-1, 1), random.uniform(0.3, 1.0)]
            stars = [new_star() for _ in range(max(40, w))]
            while time.time() < end and not _saver_tecla_enter():
                grid = [[" "] * w for _ in range(h)]
                for s in stars:
                    s[2] -= 0.025
                    if s[2] <= 0.05:
                        s[:] = new_star()
                        s[2] = 1.0
                    px = int(w / 2 + s[0] / s[2] * w / 5)
                    py = int(h / 2 + s[1] / s[2] * h / 5)
                    if 0 <= px < w and 0 <= py < h:
                        if s[2] > 0.6:
                            ch, col = ".", CYAN
                        elif s[2] > 0.3:
                            ch, col = "+", WHITE
                        else:
                            ch, col = "*", YELLOW
                        grid[py][px] = f"{col}{ch}{RESET}"
                    else:
                        s[:] = new_star()
                        s[2] = 1.0
                _saver_draw(grid)
                time.sleep(0.06)
        else:                                # reloj que rebota
            colors = [YELLOW, CYAN, GREEN, MAGENTA, WHITE]
            x, y, dx, dy, ci = 2, 1, 1, 1, 0
            while time.time() < end and not _saver_tecla_enter():
                rows_t = _big_text(datetime.now().strftime("%H:%M"), 0)
                bw, bh = len(rows_t[0]), len(rows_t)
                grid = [[" "] * w for _ in range(h)]
                for i, r in enumerate(rows_t):
                    for j, chh in enumerate(r):
                        if chh != " " and 0 <= y + i < h and 0 <= x + j < w:
                            grid[y + i][x + j] = f"{colors[ci]}{chh}{RESET}"
                x += dx
                y += dy
                if x <= 0 or x + bw >= w:
                    dx, ci = -dx, (ci + 1) % len(colors)
                    x = max(0, min(x, w - bw))
                if y <= 0 or y + bh >= h:
                    dy, ci = -dy, (ci + 1) % len(colors)
                    y = max(0, min(y, h - bh))
                _saver_draw(grid)
                time.sleep(0.12)
    except KeyboardInterrupt:
        pass
    finally:
        sys.stdout.write("\033[?25h")
        sys.stdout.flush()
        clear_screen()


_SAVER_MODES = {"estrellas": "estrellas", "stars": "estrellas", "lluvia": "lluvia", "rain": "lluvia",
                "matrix": "lluvia", "reloj": "reloj", "clock": "reloj"}


def cmd_ssaver(args=""):
    mode, secs = "estrellas", 60
    for t in args.lower().split():
        if t.isdigit():
            secs = max(1, min(3600, int(t)))
        elif t in _SAVER_MODES:
            mode = _SAVER_MODES[t]
        else:
            print(f"{RED}Uso: ssaver [estrellas | lluvia | reloj] [segundos]  (Enter para salir){RESET}")
            return
    run_app("ssaver", _saver_loop, mode, secs)


# ---------------- Autocompletado con Tab y flechas de historial ----------------

def _completer(text, state):
    if not _RL["on"]:
        return None
    try:
        buf = readline.get_line_buffer()
        low = text.lower()
        if " " not in buf.lstrip():
            names = set(BASE_COMMANDS) | set(EXTRA_COMMANDS) | set(SHELL_ALIASES) | set(system_state["aliases"])
            opts = sorted(n for n in names if n.startswith(low))
        elif ":" in low:
            d, _, part = low.partition(":")
            opts = []
            if d.upper() in disks_storage:
                opts = sorted(f"{d}:{n.lower()}" for n in disks_storage[d.upper()]["files"]
                              if n.lower().startswith(part))
        else:
            files = sorted(n.lower() for n in disks_storage[current_drive]["files"] if n.lower().startswith(low))
            drives = [f"{d.lower()}:" for d in disks_storage if f"{d.lower()}:".startswith(low)]
            opts = files + drives
        return opts[state] if state < len(opts) else None
    except Exception:
        return None


def _setup_readline():
    if readline is None:
        return
    try:
        readline.set_completer_delims(" \t\n")
        readline.set_completer(_completer)
        if "libedit" in (getattr(readline, "__doc__", "") or ""):
            readline.parse_and_bind("bind ^I rl_complete")
        else:
            readline.parse_and_bind("tab: complete")
    except Exception:
        pass


def _sync_readline_history():
    """Deja en las flechas ↑↓ solo los comandos del shell (no lo escrito en juegos o editor)."""
    if readline is None:
        return
    try:
        readline.clear_history()
        for h in system_state["history"][-100:]:
            readline.add_history(h)
    except Exception:
        pass


# ---------------- Intérprete: separa, canaliza y ejecuta ----------------

PIPE_CMDS = {
    "dir", "ls", "read", "type", "cat", "ps", "tree", "date", "whoami", "find", "grep", "stat",
    "hex", "games", "history", "alias", "echo", "neofetch", "sysinfo", "uptime", "ver", "version",
    "net", "cal", "todo", "agenda", "disk", "help", "man", "manual", "trash", "set", "df",
    "hwinfo", "share", "diff", "calc", "conv", "genpass", "mail", "correo", "paste", "curl",
    "templo", "about", "pwd",
}
FILTERS = {
    "more": cmd_more, "sort": cmd_sort, "uniq": cmd_uniq, "head": cmd_head, "tail": cmd_tail,
    "wc": cmd_wc, "grep": filter_grep, "find": filter_grep, "tee": cmd_tee, "clip": cmd_clip,
}


def _split_pipes(line):
    """Separa por '|' respetando las comillas."""
    parts, buf, quote = [], [], None
    for ch in line:
        if quote:
            buf.append(ch)
            if ch == quote:
                quote = None
        elif ch in "\"'":
            quote = ch
            buf.append(ch)
        elif ch == "|":
            parts.append("".join(buf))
            buf = []
        else:
            buf.append(ch)
    parts.append("".join(buf))
    return parts


def _split_redirect(text):
    """Devuelve (comando, '>' | '>>' | None, destino) buscando el primer '>' fuera de comillas."""
    quote = None
    for i, ch in enumerate(text):
        if quote:
            if ch == quote:
                quote = None
        elif ch in "\"'":
            quote = ch
        elif ch == ">":
            op = ">>" if text[i + 1:i + 2] == ">" else ">"
            target = text[i + len(op):].strip()
            if target and " " not in target:
                return text[:i].strip(), op, target
            return text, None, None
    return text, None, None


def _split_cmd(text):
    parts = text.split(None, 1)
    return (parts[0].lower() if parts else ""), (parts[1].strip() if len(parts) > 1 else "")


def _prep_stage(text):
    cmd, args = _split_cmd(text)
    aliases = system_state["aliases"]
    if cmd in aliases:
        cmd, args = _split_cmd(aliases[cmd] + ((" " + args) if args else ""))
    return SHELL_ALIASES.get(cmd, cmd), args


def _pipeable(cmd, args):
    if cmd == "calc" and not args:
        return False                      # la calculadora interactiva necesita el teclado
    return cmd in PIPE_CMDS or cmd in FILTERS


def _power(cmd, args):
    if cmd == "logout":
        print(f"{YELLOW}Cerrando la sesión de {system_state['user']}...{RESET}")
        time.sleep(0.5)
        save_system()
        system_state["reboot"] = True
        system_state["skip_boot"] = True
        return "reboot"
    restart = cmd in ("reboot", "restart") or (cmd == "shutdown" and "-r" in args.split())
    if restart:
        print(f"{YELLOW}Reiniciando Serpent OS...{RESET}")
    cmd_shutdown_sequence()
    if restart:
        system_state["reboot"] = True
        return "reboot"
    return "exit"





