    def ask(prompt):
        try:
            return input(prompt).strip()
        except (EOFError, KeyboardInterrupt):
            return "q"

    def run_demo(command):
        print(f"\n{CYAN}serpent>{RESET} {YELLOW}{command}{RESET}")
        try:
            execute_line(command)
        except Exception as exc:
            print(f"{RED}No se pudo mostrar esta demostración: {type(exc).__name__}: {exc}{RESET}")

    clear_screen()
    panel("SERPENT OS · TOUR DE EXPLORACIÓN")
    print(f"{WHITE}Un recorrido guiado por las funciones reales del sistema.{RESET}")
    print(f"{YELLOW}No borra archivos, no cambia ajustes y no instala paquetes.{RESET}")
    print("En cada etapa vas a ver una explicación, una demostración y un ejercicio opcional.")
    print(f"\n{CYAN}Controles:{RESET} Enter continuar · B volver · S saltar · Q salir")
    if ask(f"\n{GREEN}Presioná Enter para comenzar... {RESET}").lower() == "q":
        return

    index = 0
    completed = set()
    while 0 <= index < len(steps):
        step = steps[index]
        clear_screen()
        total = len(steps)
        bar_width = 22
        filled = int(((index + 1) / total) * bar_width)
        bar = "█" * filled + "░" * (bar_width - filled)
        panel(f"TOUR {index + 1:02d}/{total:02d} · {step['title']}")
        print(f"{CYAN}[{bar}]{RESET}  {index + 1}/{total}")
