ATLAS_SYSTEMS = json.loads(ATLAS_DATA_JSON)


def cmd_atlas(args=""):
    """Explorador offline del Atlas Serpent: mundos y expediciones."""
    parts = args.strip().split()
    if not parts or parts[0].lower() in ("help", "ayuda", "?"):
        panel("ATLAS SERPENT — EXPLORACIÓN OFFLINE")
        print(f"  {YELLOW}{len(ATLAS_SYSTEMS)} sistemas registrados.{RESET}")
        print("  atlas random             descubre un mundo al azar")
        print("  atlas 42                 abre el registro número 42")
        print("  atlas SYS-0042           abre un registro por identificador")
        print("  atlas search cristal     busca en nombres, regiones y expediciones")
        print("  atlas <palabra>          búsqueda rápida")
        print("")
        return

    action = parts[0].lower()
    if action in ("random", "azar", "aleatorio"):
        record = random.choice(ATLAS_SYSTEMS)
    elif action in ("search", "buscar"):
        query = " ".join(parts[1:]).strip().casefold()
        if not query:
            print(f"{RED}Uso: atlas search palabra{RESET}")
            return
        keys = ("id", "name", "region", "star", "world", "climate", "survey", "mission")
        hits = [r for r in ATLAS_SYSTEMS
                if query in " ".join(str(r.get(k, "")) for k in keys).casefold()]
        if not hits:
            print(f"{YELLOW}No encontré sistemas para '{query}'.{RESET}")
            return
        panel(f"RESULTADOS DEL ATLAS: {len(hits)}")
        for r in hits[:24]:
            print(f"  {CYAN}{r['id']}{RESET}  {YELLOW}{r['name']}{RESET} — {r['world']} / {r['region']}")
        if len(hits) > 24:
            print(f"  {CYAN}... y {len(hits) - 24} coincidencias más; acota la búsqueda.{RESET}")
        print("")
        return
    else:
        query = " ".join(parts)
        record = next((r for r in ATLAS_SYSTEMS if r["id"].casefold() == query.casefold()), None)
        if record is None and query.isdigit():
            index = int(query)
            if 1 <= index <= len(ATLAS_SYSTEMS):
                record = ATLAS_SYSTEMS[index - 1]
        if record is None:
            return cmd_atlas("search " + query)

    panel(f"{record['id']} — {record['name']}")
    print(f"  {CYAN}Región:{RESET} {record['region']}  |  {CYAN}Estrella:{RESET} {record['star']}")
    print(f"  {CYAN}Mundo:{RESET} {record['world']}  |  {CYAN}Clima:{RESET} {record['climate']}")
    print(f"  {CYAN}Gravedad:{RESET} {record['gravity']}  |  {CYAN}Índice:{RESET} {record['index']}")
    print(f"\n{GREEN}Registro de exploración{RESET}\n{record['survey']}")
    print(f"\n{YELLOW}Expedición sugerida{RESET}\n{record['mission']}")
    print(f"\n{MAGENTA}Bitácora histórica{RESET}\n{record['chronicle']}")
    print(f"\n{CYAN}Hallazgo estimado:{RESET} {record['reward']} créditos de expedición\n")


