def _campaign_state():
    """Devuelve el progreso de campaña, corrigiendo partidas antiguas o incompletas."""
    state = system_state.get("campaign")
    if not isinstance(state, dict):
        state = new_campaign_state()
        system_state["campaign"] = state
    defaults = new_campaign_state()
    for key, value in defaults.items():
        if key not in state or type(state[key]) is not type(value):
            state[key] = value
    rep = state.get("reputation")
    for faction in ("archivo", "colonias", "cartografos"):
        if type(rep.get(faction)) is not int:
            rep[faction] = 0
    for key in ("completed", "evidence", "allies", "journal"):
        if not isinstance(state.get(key), list):
            state[key] = []
    if not isinstance(state.get("decisions"), dict):
        state["decisions"] = {}
    if type(state.get("mission")) is not int:
        state["mission"] = 0
    state["mission"] = max(0, min(state["mission"], len(CAMPAIGN_MISSIONS)))
    if type(state.get("supplies")) is not int:
        state["supplies"] = 4
    if type(state.get("xp")) is not int:
        state["xp"] = 0
    return state


def _campaign_ending(state):
    choice = state["decisions"].get("12", "")
    rep = state["reputation"]
    if choice == "coalicion" and min(rep.values()) >= 2:
        return "tratado"
    if choice == "atlas-abierto" and len(state["evidence"]) >= 6:
        return "abierto"
    if choice == "refugios" and rep["colonias"] >= 4:
        return "refugios"
    strongest = max(rep, key=rep.get)
    if strongest == "archivo":
        return "archivo"
    if strongest == "cartografos":
        return "rutas"
    return "incierto"


def _campaign_present(mission, state):
    index = state["mission"]
    panel(f"{mission['act']}  |  CAPÍTULO {index + 1}/{len(CAMPAIGN_MISSIONS)}")
    print(f"  {BOLD}{YELLOW}{mission['title']}{RESET}")
    record = next((r for r in ATLAS_SYSTEMS if r["id"] == mission["system_id"]), None)
    if record:
        print(f"  Destino Atlas: {CYAN}{record['id']} — {record['name']}{RESET}")
        print(f"  {record['region']} | {record['world']} | {record['climate']} | gravedad {record['gravity']}")
    print(f"\n{mission['brief']}\n")
    print(f"{GREEN}Objetivo:{RESET} {mission['objective']}")
    if state["supplies"] <= 1:
        print(f"{YELLOW}Reservas de expedición: {state['supplies']} — cada decisión logística importa.{RESET}")
    if state["allies"]:
        print(f"{CYAN}Aliados en ruta:{RESET} {', '.join(state['allies'][-4:])}")
    if state["mission"] >= 6:
        rep = state["reputation"]
        print(f"{MAGENTA}Apoyos:{RESET} Archivo {rep['archivo']} | Liga {rep['colonias']} | Cartógrafos {rep['cartografos']}")
    if "puzzle" in mission:
        print(f"{YELLOW}Pista:{RESET} {mission['puzzle']['prompt'].split(':')[0]}")
        print("  Usa 'campaign play' para resolver el reto y registrar la consecuencia.")
    else:
        print(f"\n{mission['prompt']}")
        for number, choice in enumerate(mission["choices"], 1):
            print(f"  {CYAN}{number}{RESET}) {choice['label']}")
        print("  Usa 'campaign play' para tomar una decisión.")


def _campaign_finish_mission(mission, outcome):
    state = _campaign_state()
    if mission["id"] in state["completed"]:
        print(f"{YELLOW}Este capítulo ya está registrado; no se puede repetir para farmear recompensas.{RESET}")
        return
    for faction, delta in outcome.get("rep", {}).items():
        if faction in state["reputation"]:
            state["reputation"][faction] += int(delta)
    evidence = outcome.get("evidence")
    if evidence and evidence not in state["evidence"]:
        state["evidence"].append(evidence)
    ally = outcome.get("ally")
    if ally and ally not in state["allies"]:
        state["allies"].append(ally)
    state["supplies"] = max(0, state["supplies"] + int(outcome.get("supplies", 0)))
    state["xp"] += int(outcome.get("xp", 0))
    gold = int(outcome.get("gold", 0))
    potions = int(outcome.get("potions", 0))
    rpg_stats["gold"] += gold
    rpg_stats["potions"] += potions
    state["decisions"][mission["id"]] = outcome.get("decision", "resuelto")
    state["completed"].append(mission["id"])
    state["journal"].append({
        "id": mission["id"], "title": mission["title"],
        "decision": outcome.get("decision", "resuelto"),
        "result": outcome.get("result", ""),
    })
    state["journal"][:] = state["journal"][-20:]
    state["mission"] += 1
    print(f"\n{GREEN}— CONSECUENCIA —{RESET}\n{outcome.get('result', 'La expedición continúa.')}")
    print(f"{YELLOW}+{gold} oro{RESET} para tu RPG | +{potions} pociones | +{outcome.get('xp', 0)} experiencia de explorador")
    print(f"Reservas de expedición: {state['supplies']}")
    if state["mission"] >= len(CAMPAIGN_MISSIONS):
        state["status"] = "complete"
        state["ending"] = _campaign_ending(state)
        title, ending_text = CAMPAIGN_ENDINGS[state["ending"]]
        panel(f"FINAL: {title}")
        print(ending_text)
        print(f"\n{CYAN}Capítulos completados:{RESET} {len(state['completed'])}/{len(CAMPAIGN_MISSIONS)}")
        print(f"{CYAN}Evidencias reunidas:{RESET} {len(state['evidence'])} | {CYAN}Aliados:{RESET} {len(state['allies'])}")
        print(f"{GREEN}Tu oro y tus pociones del RPG se conservaron como recompensa de campaña.{RESET}\n")
    else:
        state["status"] = "active"
        next_mission = CAMPAIGN_MISSIONS[state["mission"]]
        print(f"\n{CYAN}Siguiente capítulo desbloqueado:{RESET} {next_mission['title']}")
        print("Lee la nueva escena con 'campaign show' y juega con 'campaign play'.\n")


def _campaign_play():
    state = _campaign_state()
    if state["status"] == "new":
        print(f"{YELLOW}Primero inicia la campaña con: campaign start{RESET}")
        return
    if state["status"] == "complete" or state["mission"] >= len(CAMPAIGN_MISSIONS):
        title = CAMPAIGN_ENDINGS.get(state["ending"], CAMPAIGN_ENDINGS["incierto"])[0]
        print(f"{GREEN}La campaña ya terminó: {title}. Usa campaign journal para releer el viaje.{RESET}")
        return
    mission = CAMPAIGN_MISSIONS[state["mission"]]
    _campaign_present(mission, state)
    if "puzzle" in mission:
        answer = _ask(f"\n{CYAN}{mission['puzzle']['prompt']}{RESET}")
        if answer is None:
            print(f"{YELLOW}Reto pausado; el capítulo sigue pendiente.{RESET}")
            return
        key = re.sub(r"[\s_]+", "", answer.casefold())
        accepted = {re.sub(r"[\s_]+", "", x.casefold()) for x in mission["puzzle"]["accepted"]}
        outcome = mission["puzzle"]["success"] if key in accepted else mission["puzzle"]["failure"]
    else:
        raw = _ask(f"\n{CYAN}{mission['prompt']}{RESET}")
        if raw is None:
            print(f"{YELLOW}Decisión pausada; el capítulo sigue pendiente.{RESET}")
            return
        try:
            selected = int(raw.strip()) - 1
        except ValueError:
            selected = -1
        if not 0 <= selected < len(mission["choices"]):
            print(f"{RED}Opción no válida. No se gastaron recursos; vuelve con 'campaign play'.{RESET}")
            return
        outcome = mission["choices"][selected]
    _campaign_finish_mission(mission, outcome)


def _campaign_show_map():
    state = _campaign_state()
    panel("ECOS DEL ATLAS — CARTA DE EXPEDICIÓN")
    for index, mission in enumerate(CAMPAIGN_MISSIONS):
        if mission["id"] in state["completed"]:
            mark, color = "✓", GREEN
        elif index == state["mission"] and state["status"] != "new":
            mark, color = "▶", YELLOW
        else:
            mark, color = "·", WHITE
        print(f"  {color}{mark}{RESET} {index + 1:02d}. {mission['title']}")
    print(f"\n{CYAN}Ruta:{RESET} {state['mission']}/{len(CAMPAIGN_MISSIONS)} capítulos | "
          f"{CYAN}Reservas:{RESET} {state['supplies']} | {CYAN}Experiencia:{RESET} {state['xp']}\n")


def _campaign_show_status():
    state = _campaign_state()
    panel("EXPEDICIÓN — ESTADO")
    print(f"  Estado: {state['status']} | Capítulos: {len(state['completed'])}/{len(CAMPAIGN_MISSIONS)}")
    print(f"  Reservas: {state['supplies']} | Experiencia de explorador: {state['xp']}")
    rep = state["reputation"]
    print(f"  Reputación — Archivo {rep['archivo']} | Liga {rep['colonias']} | Cartógrafos {rep['cartografos']}")
    print(f"  Evidencias: {len(state['evidence'])} | Aliados: {', '.join(state['allies']) or 'ninguno todavía'}")
    print(f"  RPG — {rpg_stats['gold']} de oro | {rpg_stats['potions']} pociones")
    if state["status"] == "complete":
        print(f"  Desenlace: {CAMPAIGN_ENDINGS.get(state['ending'], CAMPAIGN_ENDINGS['incierto'])[0]}")
    elif state["status"] == "new":
        print("  Escribe 'campaign start' para recibir el briefing.")
    elif state["mission"] < len(CAMPAIGN_MISSIONS):
        print(f"  Disponible: {CAMPAIGN_MISSIONS[state['mission']]['title']} — campaign show / campaign play")
    print("")


def _campaign_show_journal():
    state = _campaign_state()
    panel("BITÁCORA DE LA CAMPAÑA")
    if not state["journal"]:
        print("  La bitácora está vacía. Inicia con 'campaign start'.\n")
        return
    for entry in state["journal"]:
        print(f"\n{YELLOW}{entry['id']}. {entry['title']}{RESET}")
        print(f"  Decisión: {entry['decision']}")
        print(f"  {entry['result']}")
    print(f"\n{len(state['journal'])} registros narrativos guardados.\n")


def cmd_campaign(args=""):
    """Campaña narrativa ramificada, persistente y conectada con Atlas y RPG."""
    aliases = {
        "iniciar": "start", "jugar": "play", "seguir": "play", "continuar": "play",
        "ver": "show", "actual": "show", "mapa": "map", "estado": "status",
        "diario": "journal", "bitacora": "journal", "ayuda": "help",
        "reiniciar": "reset",
    }
    parts = args.strip().split()
    action = aliases.get(parts[0].casefold(), parts[0].casefold()) if parts else "help"
    state = _campaign_state()
    if action in ("help", "?"):
        panel("ECOS DEL ATLAS — CAMPAÑA")
        print("  campaign start     inicia la historia (una sola vez)")
        print("  campaign show      lee la misión actual sin decidir")
        print("  campaign play      toma una decisión o resuelve el reto")
        print("  campaign map       capítulos, desbloqueos y ruta")
        print("  campaign status    reputación, aliados, reservas y RPG")
        print("  campaign journal   relee las consecuencias")
        print("  campaign reset     reinicia solo la campaña (pide confirmación)")
        print(f"\n  {len(CAMPAIGN_MISSIONS)} capítulos escritos a mano; "
              "decisiones, acertijos y desenlaces distintos. El avance se guarda con la partida.")
        if state["status"] == "new":
            print(f"\n  {CYAN}Para empezar:{RESET} campaign start\n")
        else:
            print("")
    elif action == "start":
        if state["status"] == "new":
            state["status"] = "active"
            panel("ECOS DEL ATLAS")
            print("Una baliza repite una llamada imposible. Tres organizaciones quieren decidir qué hacer "
                  "con el mapa que la acompaña: el Archivo de Lumen, la Liga de Colonias y los Cartógrafos Libres.")
            print("No hay una ruta perfecta. Las evidencias, los suministros y las alianzas que construyas "
                  "cambiarán las escenas posteriores y el desenlace.")
            print("\nLa bitácora y las decisiones se guardan automáticamente junto a tu partida.\n")
        elif state["status"] == "complete":
            print(f"{GREEN}Ya completaste la campaña. Usa 'campaign journal' para releerla.{RESET}")
        else:
            print(f"{YELLOW}La campaña ya está en marcha; no se reinició. Capítulo actual: "
                  f"{CAMPAIGN_MISSIONS[state['mission']]['title']}.{RESET}")
        if state["status"] == "active":
            _campaign_present(CAMPAIGN_MISSIONS[state["mission"]], state)
    elif action in ("show", "mission"):
        if state["status"] == "new":
            print(f"{YELLOW}Inicia primero con 'campaign start'.{RESET}")
        elif state["status"] == "complete":
            print(f"{GREEN}La campaña terminó. Usa 'campaign journal'.{RESET}")
        else:
            _campaign_present(CAMPAIGN_MISSIONS[state["mission"]], state)
    elif action in ("play", "continue"):
        _campaign_play()
    elif action == "map":
        _campaign_show_map()
    elif action == "status":
        _campaign_show_status()
    elif action in ("journal", "log"):
        _campaign_show_journal()
    elif action == "reset":
        answer = _ask(f"{YELLOW}Esto borra el progreso, las decisiones y la bitácora de campaña. "
                      f"Escribe REINICIAR para confirmar: {RESET}")
        if answer and answer.strip().upper() == "REINICIAR":
            system_state["campaign"] = new_campaign_state()
            print(f"{GREEN}Campaña reiniciada. El oro y los objetos del RPG no se tocaron.{RESET}")
        else:
            print(f"{YELLOW}No se cambió el progreso de la campaña.{RESET}")
    else:
        print(f"{RED}Subcomando desconocido: {action}. Escribe 'campaign help'.{RESET}")


