# =====================================================================
#  BUCLE PRINCIPAL DEL SISTEMA OPERATIVO
# =====================================================================

def first_run_setup():
    """Primer arranque en este dispositivo: pide crear la palabra sagrada."""
    clear_screen()
    panel("PRIMER DESPERTAR DEL TEMPLO")
    print()
    typewriter(f"{YELLOW}La Serpiente abre un ojo... nunca te había visto en este dispositivo.{RESET}", 0.02)
    typewriter(f"{CYAN}Antes de entrar, elige la palabra sagrada que protegerá el templo.{RESET}", 0.02)
    print()
    while True:
        try:
            new = input(f"{CYAN}Nueva contraseña (mín. 3 caracteres): {RESET}").strip()
            if len(new) < 3:
                print(f"{RED}Debe tener al menos 3 caracteres.{RESET}\n")
                continue
            again = input(f"{CYAN}Repítela: {RESET}").strip()
        except (EOFError, KeyboardInterrupt):
            print(f"\n{YELLOW}Sin respuesta: se usará la contraseña por defecto '1234'. Cámbiala con 'passwd'.{RESET}")
            system_state["password"] = "1234"
            break
        if again != new:
            print(f"{RED}Las contraseñas no coinciden. Inténtalo otra vez.{RESET}\n")
            continue
        system_state["password"] = new
        print(f"{GREEN}Palabra sagrada guardada. Podrás cambiarla con 'passwd'.{RESET}")
        break
    save_system()
    time.sleep(1.2)


def choose_storage_unit():
    """Pregunta, antes de todo, qué unidad de almacenamiento usar."""
    global current_drive
    clear_screen()
    panel("SELECCIÓN DE UNIDAD DE ALMACENAMIENTO")
    print()
    for d, info in disks_storage.items():
        cap = DISK_CAPACITY.get(d, 0) // 1024
        mark = f" {GREEN}<actual>{RESET}" if d == current_drive else ""
        print(f"  [{CYAN}{d}{RESET}]  {info['label']}  ({YELLOW}{cap} KB{RESET}){mark}")
    print()
    while True:
        try:
            ans = input(f"{CYAN}¿Qué unidad quieres usar? [{'/'.join(disks_storage)}] (Enter = {current_drive}): {YELLOW}").strip().upper().rstrip(":")
        except EOFError:
            ans = ""
        print(RESET, end="")
        if not ans:
            break
        if ans in disks_storage:
            current_drive = ans
            break
        print(f"{RED}Unidad no válida. Elige {', '.join(disks_storage)}.{RESET}")
    print(f"{GREEN}* Click-clack * Unidad [{current_drive}:] seleccionada.{RESET}")
    time.sleep(0.6)


def main():
    atexit.register(lambda: print("\033[0m", end=""))
    atexit.register(save_system)
    reset_runtime()
    first_time = not os.path.exists(SAVE_FILE)   # sin archivo de guardado = primer inicio aquí
    load_system()
    choose_storage_unit()
    _pkg_refresh_extensions()
    serpent_event("Proceso de arranque iniciado", "info", "boot")
    if first_time:
        first_run_setup()
    if not system_state.pop("skip_boot", False):     # 'logout' salta la BIOS
        bios_sequence()
        KERNEL.boot(verbose=True)
        temple_boot()
    else:
        KERNEL.boot(verbose=False)
    _services_boot()
    serpent_boot_sequence()
    username = login_system()
    system_state["user"] = username
    serpent_event(f"Sesión iniciada: {username}", "info", "login")
    _set_title(f"Serpent OS - {username}@{system_state['hostname']}")
    try:
        new_mail = mail_on_boot(username)
    except Exception:   # el correo nunca debe impedir que Serpent OS arranque
        new_mail = []
    save_system()
    clear_screen()
    print_banner(username)
    mail_toast(new_mail)
    _setup_readline()
    result = _run_autoexec()

    while not result:
        _sync_readline_history()
        _RL["on"] = True
        try:
            line = input(f"{GREEN}{username}@{system_state['hostname']}{RESET} {YELLOW}{current_drive}:/Home>{RESET} ").strip()
        except EOFError:
            cmd_shutdown_sequence()
            break
        except KeyboardInterrupt:
            print(f"\n{YELLOW}(Usa 'exit' para apagar Serpent OS){RESET}")
            continue
        finally:
            _RL["on"] = False
        if not line:
            continue

        if line.startswith("!"):
            line = expand_history(line)
            if line is None:
                continue
            print(f"{YELLOW}{line}{RESET}")
        if not system_state["history"] or system_state["history"][-1] != line:
            system_state["history"].append(line)
            del system_state["history"][:-200]

        KERNEL.syscall("exec", line.split()[0] if line.split() else "")
        result = execute_line(line)
        KERNEL.tick()
        if not result:
            save_system()   # autoguardado tras cada comando


# =====================================================================
#  SerpentCore IDT — Tabla de Descriptores de Interrupción + Syscalls
#  Los programas ya no llaman funciones de Python directamente: disparan
#  interrupciones. La CPU virtual busca el vector en la IDT, comprueba el
#  nivel de privilegio (DPL) de la puerta, cambia a ring 0, ejecuta la
#  rutina de servicio (ISR) y vuelve con IRET dejando el resultado en los
#  registros.
#    * 0x00-0x1F  excepciones de CPU (#DE, #UD, #GP, #PF...)
#    * 0x08-0x0F  IRQ del PIC 8259 (modo real, como en MS-DOS)
#    * 0x10       servicios de vídeo BIOS     * 0x16  teclado BIOS
#    * 0x1A       reloj BIOS                  * 0x21  servicios DOS
#    * 0x80       llamadas al sistema estilo Linux (EAX = número)
# =====================================================================
class CPUFault(Exception):
    def __init__(self, vector, msg=""):
        super().__init__(msg)
        self.vector = vector


class _Regs(dict):
    """Registros de la CPU virtual. AH/AL son vistas de AX, como en x86."""
    NAMES = ("AX", "BX", "CX", "DX", "SI", "DI", "BP", "SP", "DS", "ES", "FLAGS")

    def __init__(self, **kw):
        super().__init__({n: 0 for n in self.NAMES})
        for k, v in kw.items():
            self[k] = v

    def _norm(self, k):
        k = k.upper()
        return k[1:] if len(k) == 3 and k[0] == "E" else k   # EAX -> AX

    def __getitem__(self, k):
        k = self._norm(k)
        if k in ("AH", "AL", "BH", "BL", "CH", "CL", "DH", "DL"):
            base = dict.__getitem__(self, k[0] + "X")
            base = base if isinstance(base, int) else 0
            return (base >> 8) & 0xFF if k[1] == "H" else base & 0xFF
        return dict.get(self, k, 0)

    def __setitem__(self, k, v):
        k = self._norm(k)
        if k in ("AH", "AL", "BH", "BL", "CH", "CL", "DH", "DL"):
            base = dict.get(self, k[0] + "X", 0)
            base = base if isinstance(base, int) else 0
            v = int(v) & 0xFF
            base = (base & 0x00FF) | (v << 8) if k[1] == "H" else (base & 0xFF00) | v
            dict.__setitem__(self, k[0] + "X", base)
        else:
            dict.__setitem__(self, k, v)

    @property
    def CF(self):
        return self["FLAGS"] & 1 if isinstance(self["FLAGS"], int) else 0

    def set_cf(self, on):
        self["FLAGS"] = (self["FLAGS"] | 1) if on else (self["FLAGS"] & ~1)


class InterruptDescriptorTable:
    SIZE = 256
    EXC_NAMES = {0x00: "#DE Division Error", 0x01: "#DB Debug", 0x02: "NMI", 0x03: "#BP Breakpoint",
                 0x04: "#OF Overflow", 0x05: "#BR Bound Range", 0x06: "#UD Invalid Opcode",
                 0x07: "#NM Device N/A", 0x0D: "#GP General Protection", 0x0E: "#PF Page Fault"}
    PIC_BASE = 0x08                     # IRQ0 -> INT 08h (modo real, como DOS)

    def __init__(self, kernel):
        self.k = kernel
        self.gates = {}                 # vector -> dict(name, handler, dpl, kind)
        self.count = {}
        self.ring = 0                   # nivel de privilegio actual (0 núcleo / 3 usuario)
        self.depth = 0
        self.trace = []                 # últimas interrupciones (para 'idt trace')
        self.out = lambda s: (sys.stdout.write(s), sys.stdout.flush())
        self.inp = lambda prompt="": builtins.input(prompt)
        self.exit_code = None
        self._install_default()

    # ---------------------------------------------------------- tabla
    def set_gate(self, vector, name, handler, dpl=0, kind="interrupt"):
        if not 0 <= vector < self.SIZE:
            raise ValueError("vector fuera de rango")
        self.gates[vector] = {"name": name, "handler": handler, "dpl": dpl, "kind": kind}

    def _install_default(self):
        for v, n in self.EXC_NAMES.items():
            dpl = 3 if v in (0x03, 0x04) else 0          # INT3/INTO permitidos en ring 3
            self.set_gate(v, n, self._isr_exception, dpl, "trap" if v in (0x01, 0x03, 0x04) else "fault")
        for irq in range(8):
            name = self.k.irq_names.get(irq, f"irq{irq}")
            self.set_gate(self.PIC_BASE + irq, f"IRQ{irq} {name}", self._isr_irq, 0, "interrupt")
        self.set_gate(0x10, "BIOS vídeo", self._isr_video, 3, "trap")
        self.set_gate(0x16, "BIOS teclado", self._isr_keyboard, 3, "trap")
        self.set_gate(0x1A, "BIOS reloj", self._isr_clock, 3, "trap")
        self.set_gate(0x20, "DOS terminar", self._isr_terminate, 3, "trap")
        self.set_gate(0x21, "DOS servicios", self._isr_dos, 3, "trap")
        self.set_gate(0x80, "syscall Linux", self._isr_syscall, 3, "trap")

    # ---------------------------------------------------------- despacho
    def interrupt(self, vector, regs=None, software=True, **kw):
        """Instrucción INT n. Devuelve los registros tras IRET."""
        regs = regs if isinstance(regs, _Regs) else _Regs(**(regs or {}))
        for k, v in kw.items():
            regs[k] = v
        vector = int(vector) & 0xFF
        gate = self.gates.get(vector)
        self.count[vector] = self.count.get(vector, 0) + 1
        self.trace.append((round(self.k.uptime(), 4), vector, self.ring,
                           regs["AH"] if vector != 0x80 else regs["AX"]))
        del self.trace[:-64]
        if gate is None:
            return self._raise_fault(0x0D, f"INT {vector:02X}h: puerta no presente en la IDT", regs)
        if software and self.ring > gate["dpl"]:
            # Igual que x86: ring 3 no puede invocar una puerta con DPL 0.
            return self._raise_fault(0x0D, f"INT {vector:02X}h: DPL={gate['dpl']} < CPL={self.ring}", regs)
        if self.depth > 16:
            self.k.panic_soft("double fault: anidamiento de interrupciones excesivo")
            raise CPUFault(0x08, "double fault")
        prev, self.ring = self.ring, 0       # cambio a ring 0
        self.depth += 1
        try:
            gate["handler"](vector, regs)
        finally:
            self.depth -= 1
            self.ring = prev                 # IRET
        return regs

    def _raise_fault(self, vector, msg, regs):
        self.count[vector] = self.count.get(vector, 0) + 1
        self.k._klog(f"trap: {self.EXC_NAMES.get(vector, hex(vector))}: {msg}", "error")
        raise CPUFault(vector, msg)

    def irq(self, n):
        """Interrupción de hardware: no comprueba DPL."""
        v = self.PIC_BASE + n if n < 8 else 0x70 + (n - 8)
        if v not in self.gates:
            self.set_gate(v, f"IRQ{n} {self.k.irq_names.get(n, '?')}", self._isr_irq, 0)
        self.count[v] = self.count.get(v, 0) + 1

    def fault_from_exception(self, e):
        """Traduce una excepción de Python del programa a la excepción de CPU equivalente."""
        if isinstance(e, CPUFault):
            return e.vector
        if isinstance(e, ZeroDivisionError):
            v = 0x00
        elif isinstance(e, (NameError, SyntaxError, AttributeError, TypeError)):
            v = 0x06
        elif isinstance(e, (MemoryError, RecursionError)):
            v = 0x0E
        else:
            v = 0x0D
        self.count[v] = self.count.get(v, 0) + 1
        self.k._klog(f"trap: {self.EXC_NAMES[v]} ({type(e).__name__})", "error")
        return v

    # ---------------------------------------------------------- ISR
    def _isr_exception(self, v, r):
        self.k._klog(f"trap: {self.EXC_NAMES.get(v)} (software)", "warn")
        if v not in (0x01, 0x03, 0x04):
            raise CPUFault(v, self.EXC_NAMES.get(v, ""))

    def _isr_irq(self, v, r):
        n = v - self.PIC_BASE
        self.k.irq_count[n] = self.k.irq_count.get(n, 0) + 1

    def _isr_video(self, v, r):
        ah = r["AH"]
        if ah == 0x00:                       # fijar modo de vídeo -> limpia pantalla
            clear_screen()
        elif ah == 0x0E:                     # teletipo: carácter en AL
            self.out(chr(r["AL"]))
        elif ah == 0x0F:                     # modo actual
            r["AL"], r["AH"], r["BH"] = 0x03, _term_cols() & 0xFF, 0
        elif ah == 0x13:                     # escribir cadena (ES:BP -> aquí BP = str)
            self.out(str(r["BP"]))
        else:
            r.set_cf(True)

    def _isr_keyboard(self, v, r):
        ah = r["AH"]
        if ah in (0x00, 0x10):
            s = self.inp("")
            ch = s[:1] or "\r"
            r["AL"], r["AH"] = ord(ch) & 0xFF, 0
        elif ah == 0x01:
            r["AX"] = 0
            r["FLAGS"] = r["FLAGS"] | 0x40   # ZF=1: no hay tecla
        else:
            r.set_cf(True)

    def _isr_clock(self, v, r):
        if r["AH"] == 0x00:
            t = int(self.k.uptime() * 18.2065)   # ticks del PIT desde el arranque
            r["CX"], r["DX"], r["AL"] = (t >> 16) & 0xFFFF, t & 0xFFFF, 0
        else:
            r.set_cf(True)

    def _isr_terminate(self, v, r):
        self.exit_code = 0
        raise SystemExit(0)

    def _isr_dos(self, v, r):
        ah = r["AH"]
        r.set_cf(False)
        if ah == 0x01:                       # leer carácter con eco
            s = self.inp("")
            r["AL"] = ord(s[:1] or "\r") & 0xFF
        elif ah == 0x02:                     # escribir carácter DL
            self.out(chr(r["DL"]))
        elif ah == 0x09:                     # escribir cadena DS:DX terminada en '$'
            s = str(r["DX"])
            self.out(s.split("$", 1)[0])
        elif ah == 0x0A:                     # entrada con buffer -> DX
            r["DX"] = self.inp(str(r["SI"]) if r["SI"] else "")
            r["AL"] = len(r["DX"]) & 0xFF
        elif ah == 0x2A:                     # fecha
            d = datetime.now()
            r["CX"], r["DH"], r["DL"], r["AL"] = d.year, d.month, d.day, (d.weekday() + 1) % 7
        elif ah == 0x2C:                     # hora
            d = datetime.now()
            r["CH"], r["CL"], r["DH"], r["DL"] = d.hour, d.minute, d.second, d.microsecond // 10000
        elif ah == 0x30:                     # versión de DOS
            r["AL"], r["AH"] = 5, 2
        elif ah == 0x4C:                     # terminar con código AL
            self.exit_code = r["AL"]
            raise SystemExit(r["AL"])
        else:
            r["AX"] = 0x01                   # función inválida
            r.set_cf(True)
            self.k._klog(f"INT 21h: función AH={ah:02X}h no implementada", "warn")

    def _isr_syscall(self, v, r):
        """INT 80h: EAX = número de syscall, EBX/ECX/EDX = argumentos, EAX = retorno."""
        k = self.k
        nr = r["AX"]
        names = {n: s for s, n in k.SYSCALLS.items()}
        name = names.get(nr)
        if name is None:
            k.syscall(f"nr{nr}")
            r["AX"] = -ENOSYS
            return
        k.syscall(name)
        b, c, d = r["BX"], r["CX"], r["DX"]
        if name == "write":                  # write(fd, buf, len)
            s = str(c) if d in (0, None) else str(c)[:int(d)]
            self.out(s)
            r["AX"] = len(s)
        elif name == "read":                 # read(fd, prompt) -> ECX = texto
            r["CX"] = self.inp(str(c) if c else "")
            r["AX"] = len(r["CX"])
        elif name == "getpid":
            r["AX"] = k.foreground or 0
        elif name == "uname":
            r["AX"] = 0
            r["CX"] = f"{k.NAME} {k.VERSION} {k.ARCH}"
        elif name == "sched_yield":
            k.tick(1)
            r["AX"] = 0
        elif name == "kill":                 # kill(pid, sig)
            res = k.kill(int(b), int(c or SIGTERM), sender_uid=1000)
            r["AX"] = -res if isinstance(res, int) and res > 0 else 0
        elif name == "setpriority":
            res = k.renice(int(b), int(c))
            r["AX"] = -res if isinstance(res, int) and res > 0 else 0
        elif name == "exit":
            self.exit_code = int(b or 0)
            raise SystemExit(self.exit_code)
        elif name == "clip_write":
            ok, _e = _clip_run(True, str(c))
            r["AX"] = 0 if ok else -EINVAL
        elif name == "clip_read":
            ok, val = _clip_run(False)
            r["CX"], r["AX"] = (val if ok else ""), (0 if ok else -EINVAL)
        else:
            r["AX"] = 0


KERNEL.idt = InterruptDescriptorTable(KERNEL)
_orig_kernel_irq = SerpentKernel.irq


def _kernel_irq_via_idt(self, n):
    _orig_kernel_irq(self, n)
    idt = getattr(self, "idt", None)
    if idt:
        idt.irq(n)


SerpentKernel.irq = _kernel_irq_via_idt


def _idt_wrap_game_ns(ns):
    """Hace que print()/input() del programa pasen por INT 80h, y expone INT n."""
    idt = KERNEL.idt
    game_print, game_input = ns["print"], ns["input"]

    def _out(s):
        game_print(s, end="", flush=True)

    def _inp(prompt=""):
        return game_input(prompt)

    def _print(*a, sep=" ", end="\n", file=None, flush=False):
        if file not in (None, sys.stdout):
            return game_print(*a, sep=sep, end=end, file=file, flush=flush)
        idt.interrupt(0x80, AX=KERNEL.SYSCALLS["write"], BX=1,
                      CX=(sep if sep is not None else " ").join(map(str, a)) + (end if end is not None else "\n"))

    def _input(prompt=""):
        return idt.interrupt(0x80, AX=KERNEL.SYSCALLS["read"], BX=0, CX=str(prompt))["CX"]

    def _int(vector, **regs):
        """INT n desde el programa (ring 3). Devuelve los registros."""
        prev_out, prev_inp, prev_ring = idt.out, idt.inp, idt.ring
        idt.out, idt.inp, idt.ring = _out, _inp, 3
        try:
            return idt.interrupt(vector, **regs)
        finally:
            idt.out, idt.inp, idt.ring = prev_out, prev_inp, prev_ring

    def _wrap(fn):
        def inner(*a, **kw):
            prev_out, prev_inp, prev_ring = idt.out, idt.inp, idt.ring
            idt.out, idt.inp, idt.ring = _out, _inp, 3
            try:
                return fn(*a, **kw)
            finally:
                idt.out, idt.inp, idt.ring = prev_out, prev_inp, prev_ring
        return inner

    def _syscall(name, ebx=0, ecx=0, edx=0):
        nr = KERNEL.SYSCALLS.get(name, name if isinstance(name, int) else -1)
        return _int(0x80, AX=nr, BX=ebx, CX=ecx, DX=edx)["AX"]

    ns["print"], ns["input"] = _wrap(_print), _wrap(_input)
    ns["int86"], ns["INT"], ns["syscall"] = _int, _int, _syscall
    ns["CPUFault"] = CPUFault


def _parse_regs(tokens):
    """Como DEBUG.COM: los números son hexadecimales (sufijo 'd' = decimal)."""
    regs = {}
    for t in tokens:
        if "=" not in t:
            continue
        k, v = t.split("=", 1)
        v = v.strip('"').strip("'")
        lv = v.lower()
        try:
            if lv.endswith("d") and lv[:-1].isdigit():
                regs[k.upper()] = int(lv[:-1])
            else:
                regs[k.upper()] = int(lv[:-1] if lv.endswith("h") else lv, 16)
        except ValueError:
            regs[k.upper()] = v.replace("_", " ")
    return regs


def _parse_vector(s):
    s = s.strip().lower()
    if s.endswith("h"):
        return int(s[:-1], 16)
    return int(s, 16) if s.startswith("0x") else int(s, 16)   # como en ensamblador: INT 21 = 21h


def cmd_idt(args=""):
    idt = KERNEL.idt
    a = args.split()
    if a and a[0] == "trace":
        if not idt.trace:
            print("  (sin interrupciones registradas)")
            return
        print(f"  {'TIEMPO':>10}  VEC  RING  AH/EAX")
        for t, v, ring, ah in idt.trace[-20:]:
            print(f"  {t:>10.4f}  {v:02X}h   {ring}    {ah}")
        return
    if a:
        try:
            v = _parse_vector(a[0])
        except ValueError:
            print(f"{RED}Uso: idt [VECTOR|trace]{RESET}")
            return
        g = idt.gates.get(v)
        if not g:
            print(f"  Vector {v:02X}h: puerta no presente (P=0) -> #GP si se invoca.")
            return
        print(f"  {CYAN}Vector {v:02X}h{RESET}  {g['name']}")
        print(f"  Tipo: {g['kind']} gate   DPL: {g['dpl']}   Presente: sí")
        print(f"  ISR: {g['handler'].__name__}   Disparos: {idt.count.get(v, 0)}")
        return
    print(f"  {BOLD}IDT de {KERNEL.NAME}{RESET} — {len(idt.gates)}/{idt.SIZE} puertas presentes")
    print(f"  {'VEC':<5}{'TIPO':<11}{'DPL':<5}{'DISPAROS':>9}  NOMBRE")
    for v in sorted(idt.gates):
        g = idt.gates[v]
        col = RED if g["kind"] == "fault" else (YELLOW if v >= 0x10 else GREEN)
        print(f"  {col}{v:02X}h{RESET}  {g['kind']:<11}{g['dpl']:<5}{idt.count.get(v, 0):>9}  {g['name']}")
    print(f"  {CYAN}Prueba: int 21 AH=09 DX=Hola_mundo$   ·   int 80 EAX=27 (getpid)   ·   idt 21{RESET}")


def cmd_int(args=""):
    a = args.split()
    if not a:
        print(f"{RED}Uso: int VECTOR [REG=valor ...]   (ej. int 21 AH=09 DX=Hola$){RESET}")
        return
    try:
        v = _parse_vector(a[0])
    except ValueError:
        print(f"{RED}Vector inválido: {a[0]}{RESET}")
        return
    regs = _parse_regs(a[1:])
    idt = KERNEL.idt
    prev = idt.ring
    idt.ring = 3                               # el shell es un programa de usuario
    try:
        r = idt.interrupt(v, **regs)
        print()
        shown = {k: val for k, val in r.items() if val not in (0, "")}
        print(f"  {GREEN}IRET{RESET} " + "  ".join(
            f"{k}={val:04X}h" if isinstance(val, int) and val >= 0 else f"{k}={val!r}" for k, val in shown.items()))
    except CPUFault as e:
        print(f"{RED}  ¡Excepción {idt.EXC_NAMES.get(e.vector, hex(e.vector))}! {e}{RESET}")
    except SystemExit as e:
        print(f"{YELLOW}  Programa terminado con código {e.code}{RESET}")
    finally:
        idt.ring = prev


