def _module_load(name, chain=None):
    name = name.lower().removesuffix(".ko")
    chain = [] if chain is None else chain
    if name in chain:
        return False, "dependencia circular: " + " -> ".join(chain + [name])
    if name in KERNEL.modules:
        return True, f"{name}: ya estaba cargado"
    spec = SERPENT_MODULES.get(name)
    if spec is None:
        return False, f"módulo desconocido: {name} (usa 'modprobe -l')"
    for dep in spec["deps"]:
        ok, msg = _module_load(dep, chain + [name])
        if not ok:
            return False, f"{name}: no se pudo cargar dependencia {dep}: {msg}"
    KERNEL.modules[name] = {
        "desc": spec["desc"], "loaded": time.time(), "refs": 0,
        "builtin": False, "deps": list(spec["deps"]),
    }
    KERNEL._klog(f"module: {name} cargado ({spec['desc']})")
    return True, f"{name}: módulo cargado"


def _module_unload(name):
    name = name.lower().removesuffix(".ko")
    info = KERNEL.modules.get(name)
    if info is None:
        return False, f"{name}: módulo no está cargado"
    if name in SERPENT_CORE_MODULES or info.get("builtin"):
        return False, f"{name}: módulo esencial, no se puede descargar"
    users = [m for m, data in KERNEL.modules.items()
             if name in data.get("deps", [])]
    if users:
        return False, f"{name}: ocupado por {', '.join(users)}"
    if info.get("refs", 0):
        return False, f"{name}: módulo en uso ({info['refs']} referencias)"
    del KERNEL.modules[name]
    KERNEL._klog(f"module: {name} descargado", "warn")
    return True, f"{name}: módulo descargado"


def cmd_modprobe(args=""):
    a = args.split()
    if not a or a[0] in ("-l", "--list"):
        panel("CATÁLOGO DE MÓDULOS")
        for name, spec in sorted(SERPENT_MODULES.items()):
            state = f"{GREEN}CARGADO{RESET}" if name in KERNEL.modules else f"{YELLOW}disponible{RESET}"
            deps = ", ".join(spec["deps"]) or "-"
            print(f"  {MAGENTA}{name:<14}{RESET} {state:<18} deps: {deps}")
            print(f"    {spec['desc']}")
        print("\nUso: modprobe nombre | modprobe -r nombre")
        return
    remove = a[0] in ("-r", "--remove")
    name = a[1] if remove and len(a) > 1 else (a[0] if not remove else "")
    if not name:
        print(f"{RED}Uso: modprobe [-r] módulo{RESET}")
        return
    ok, msg = _module_unload(name) if remove else _module_load(name)
    print(f"{GREEN if ok else RED}{msg}{RESET}")


def cmd_rmmod(args=""):
    if not args.strip():
        print(f"{RED}Uso: rmmod módulo{RESET}")
        return
    ok, msg = _module_unload(args.split()[0])
    print(f"{GREEN if ok else RED}{msg}{RESET}")


def cmd_devtree(args=""):
    panel("ÁRBOL DE DISPOSITIVOS SERPENT")
    print("Serpent-Platform")
    print("├── cpu0  [virtual] " + (platform.processor() or platform.machine() or "CPU anfitriona"))
    print(f"├── memory [virtual] {KERNEL.TOTAL_PAGES * KERNEL.PAGE_KB} KB / páginas de {KERNEL.PAGE_KB} KB")
    print("├── bus-isa")
    for dev, kind, desc in SERPENT_DEVICES:
        module = SERPENT_DEVICE_MODULE.get(dev)
        if module:
            state = f"{GREEN}online{RESET}" if module in KERNEL.modules else f"{RED}sin controlador{RESET}"
        else:
            state = f"{GREEN}online{RESET}"
        print(f"│   ├── {dev:<8} [{kind:<7}] {desc}  {state}")
    print("└── host-bridge")
    print(f"    ├── {platform.system()} {platform.release()}")
    print(f"    ├── {os.cpu_count() or 1} CPU lógicos")
    print(f"    └── Python {platform.python_version()}")
    print(f"\n{YELLOW}Nota: los dispositivos Serpent son virtuales; el puente anfitrión informa del equipo real.{RESET}")


