def _pkg_refresh_extensions():
    """Registra únicamente comandos pertenecientes a paquetes instalados."""
    old=globals().get("_SERPENT_ACTIVE_EXTENSION_COMMANDS",set())
    for command in old:
        EXTRA_COMMANDS.pop(command,None)
        if command in BASE_COMMANDS: BASE_COMMANDS.remove(command)
        MAN_PAGES.pop(command,None)
    active=set(); help_rows=[]
    for name in SERPENT_INSTALLED_PACKAGES:
        spec=SERPENT_PACKAGE_REPO.get(name)
        if not spec: continue
        command=spec["command"]; active.add(command)
        EXTRA_COMMANDS[command]=lambda args="",f=command: _pkg_extension_run(f,args)
        if command not in BASE_COMMANDS: BASE_COMMANDS.append(command)
        help_rows.append((f"{command} [argumentos]",spec["desc"]))
        MAN_PAGES[command]=(f"{command} [argumentos]",spec["desc"],
            [f"Lo proporciona el paquete opcional {name}.",f"Instálalo con: pkg install {name}","Consulta pkg info para ver sus detalles."],
            ["pkg","help"])
    globals()["_SERPENT_ACTIVE_EXTENSION_COMMANDS"]=active
    EXTRA_HELP_SECTIONS[:]=[row for row in EXTRA_HELP_SECTIONS if row[0]!="EXTENSIONES INSTALADAS"]
    if help_rows: EXTRA_HELP_SECTIONS.append(("EXTENSIONES INSTALADAS",help_rows))


def _pkg_install(name, chain=None):
    name=name.lower(); spec=SERPENT_PACKAGE_REPO.get(name)
    if spec is None: return False,f"paquete no encontrado: {name}"
    if name in SERPENT_INSTALLED_PACKAGES: return True,f"{name}: ya está instalado"
    SERPENT_INSTALLED_PACKAGES[name]=spec["version"]
    serpent_event(f"Extensión instalada: {name}", "info", "pkg")
    _pkg_refresh_extensions()
    if not save_system():
        SERPENT_INSTALLED_PACKAGES.pop(name,None); _pkg_refresh_extensions()
        return False,f"{name}: no se pudo guardar la instalación"
    print(f"  {GREEN}instalado{RESET} {name} ({spec['version']}) · {spec['size']} KB")
    return True,f"{name}: extensión activada y guardada"


def _pkg_remove(name):
    name=name.lower()
    if name not in SERPENT_INSTALLED_PACKAGES: return False,f"{name}: no está instalado"
    version=SERPENT_INSTALLED_PACKAGES.pop(name)
    serpent_event(f"Extensión desinstalada: {name}", "warn", "pkg")
    _pkg_refresh_extensions()
    if not save_system():
        SERPENT_INSTALLED_PACKAGES[name]=version; _pkg_refresh_extensions()
        return False,f"{name}: no se pudo guardar la desinstalación"
    return True,f"{name}: extensión desactivada y eliminada"


def cmd_pkg(args=""):
    global SERPENT_REPO_REFRESHED
    a=args.split(); action=a[0].lower() if a else "list"
    if action in ("list","ls","-l"):
        panel("SERPENT PKG · REPOSITORIO DE EXTENSIONES")
        print(f"{len(SERPENT_PACKAGE_REPO)} extensiones opcionales | instaladas: {len(SERPENT_INSTALLED_PACKAGES)}")
        print(f"  {'PAQUETE':<24} {'COMANDO':<16} {'ESTADO':<12} DESCRIPCIÓN")
        for name,spec in SERPENT_PACKAGE_REPO.items():
            installed=name in SERPENT_INSTALLED_PACKAGES
            state=f"{GREEN}instalado{RESET}" if installed else f"{YELLOW}disponible{RESET}"
            print(f"  {name:<24} {spec['command']:<16} {state:<12} {spec['desc']}")
        print("\nUso: pkg install|remove|search|info|installed|categories|update|upgrade")
    elif action in ("installed","list-installed"):
        panel("EXTENSIONES INSTALADAS")
        if not SERPENT_INSTALLED_PACKAGES: print("(ninguna; todas las extensiones son opcionales)")
        for name,version in SERPENT_INSTALLED_PACKAGES.items():
            print(f"  {GREEN}{name:<24}{RESET} {version} -> {SERPENT_PACKAGE_REPO[name]['command']}")
    elif action in ("categories","category"):
        counts={}
        for spec in SERPENT_PACKAGE_REPO.values(): counts[spec["category"]]=counts.get(spec["category"],0)+1
        panel("CATEGORÍAS DEL REPOSITORIO")
        for cat,count in sorted(counts.items()):
            installed=sum(1 for n in SERPENT_INSTALLED_PACKAGES if SERPENT_PACKAGE_REPO[n]["category"]==cat)
            print(f"  {cat:<12} {count:>2} paquetes | {installed} instalados")
    elif action in ("install","add"):
        if len(a)<2: print("Uso: pkg install paquete"); return
        ok,msg=_pkg_install(a[1]); print(f"{GREEN if ok else RED}{msg}{RESET}")
    elif action in ("remove","uninstall","del"):
        if len(a)<2: print("Uso: pkg remove paquete"); return
        ok,msg=_pkg_remove(a[1]); print(f"{GREEN if ok else RED}{msg}{RESET}")
    elif action=="search":
        if len(a)<2: print("Uso: pkg search texto"); return
        term=" ".join(a[1:]).lower()
        matches=[(n,s) for n,s in SERPENT_PACKAGE_REPO.items() if term in n.lower() or term in s["desc"].lower() or term in s["category"]]
        for n,s in matches: print(f"  {n:<24} {'[instalado]' if n in SERPENT_INSTALLED_PACKAGES else '[disponible]'}  {s['desc']}")
        if not matches: print("No hay paquetes que coincidan.")
    elif action=="info":
        if len(a)<2 or a[1] not in SERPENT_PACKAGE_REPO: print("Uso: pkg info paquete"); return
        n=a[1]; s=SERPENT_PACKAGE_REPO[n]
        print(f"{CYAN}{n}{RESET} {s['version']} · {s['category']}")
        print(f"  {s['desc']}\n  Comando añadido: {s['command']}\n  Tamaño estimado: {s['size']} KB")
        print(f"  Dependencias: ninguna (extensión independiente)")
        print(f"  Estado: {'instalado' if n in SERPENT_INSTALLED_PACKAGES else 'disponible'}")
    elif action=="update":
        SERPENT_REPO_REFRESHED=time.time()
        print(f"{GREEN}Índice local actualizado: {len(SERPENT_PACKAGE_REPO)} extensiones.{RESET}")
        print(f"{YELLOW}Catálogo incluido con Serpent OS; no se descargó software externo.{RESET}")
    elif action in ("upgrade","update-all"):
        print(f"{GREEN}Comprobación completada: {len(SERPENT_INSTALLED_PACKAGES)} extensiones instaladas.{RESET}")
        save_system()
    else:
        print(f"{RED}Acción desconocida. Usa: pkg list|install|remove|search|info|installed|categories|update|upgrade{RESET}")


def cmd_pkgcheck(args=""):
    invalid=[n for n in SERPENT_INSTALLED_PACKAGES if n not in SERPENT_PACKAGE_REPO]
    if invalid:
        print(f"{RED}Paquetes inconsistentes: {', '.join(invalid)}{RESET}")
    else:
        print(f"{GREEN}Integridad correcta: {len(SERPENT_INSTALLED_PACKAGES)} extensiones instaladas; todas son opcionales e independientes.{RESET}")


