# ---------------- SERPENT BOOT SEQUENCE ----------------
def serpent_boot_sequence():
    """Secuencia de inicio legible; informa sobre subsistemas virtuales."""
    clear_screen()
    panel("SERPENT OS · BOOT SEQUENCE")
    print(f"  {WHITE}Inicializando el entorno...{RESET}\n")
    stages = [
        ("Runtime Python", lambda: platform.python_version()),
        ("Kernel SerpentCore", lambda: f"{KERNEL.NAME} {KERNEL.VERSION}"),
        ("Unidades virtuales", lambda: ", ".join(d + ":" for d in disks_storage)),
        ("Extensiones", lambda: f"{len(SERPENT_INSTALLED_PACKAGES)}/50 paquetes restaurados"),
        ("Servicios", lambda: f"{sum(1 for v in SERPENT_SERVICES.values() if v['state'] == 'active')} activos"),
        ("Registro de eventos", lambda: f"{len(system_state.get('events', []))} entradas"),
    ]
    failed = 0
    for label, check in stages:
        try:
            detail = check()
            print(f"  {CYAN}[BOOT]{RESET} {label:<25} {GREEN}OK{RESET}  {WHITE}{detail}{RESET}")
        except Exception as exc:
            failed += 1
            print(f"  {CYAN}[BOOT]{RESET} {label:<25} {RED}WARN{RESET} {type(exc).__name__}")
        time.sleep(0.10)
    if failed:
        serpent_event(f"Inicio completado con {failed} aviso(s)", "warn", "boot")
    else:
        serpent_event("Secuencia de inicio completada correctamente", "info", "boot")
    print(f"\n  {GREEN}Serpent OS está listo.{RESET}")
    time.sleep(0.35)


