def _sc_ide(io, start_name=None):
    p, ask, clr = io["print"], io["input"], io["clear"]
    prog, name = [], None
    if start_name:
        d, f = resolve_path(start_name)
        f = f.upper()
        if not f.endswith(SC_EXT): f += SC_EXT
        name = f"{d}:{f}"
        prog = disks_storage.get(d, {}).get("files", {}).get(f, "").splitlines()

    def listing():
        clr()
        p(f"{CYAN}SerpentC IDE · {name or 'sin nombre'} · {len(prog)} línea(s) · .ayuda{RESET}")
        p(f"{CYAN}{'─' * 40}{RESET}")
        depth = 0
        for i, l in enumerate(prog[-200:], max(1, len(prog) - 199)):
            w = (l.strip().lower().split() or [""])[0]
            if w in ("fin", "sino"): depth = max(0, depth - 1)
            p(f"{YELLOW}{i:>3}{RESET} {'  ' * depth}{l.strip()}")
            if w in ("si", "mientras", "repetir", "para", "funcion", "función", "comando", "sino"): depth += 1
        p(f"{CYAN}{'─' * 40}{RESET}")

    def save(target):
        nonlocal name
        d, f = resolve_path(target)
        f = f.upper()
        if not f.endswith(SC_EXT): f += SC_EXT
        if d not in disks_storage:
            p(f"{RED}Unidad {d}: no encontrada.{RESET}"); return False
        text = "\n".join(prog) + "\n"
        previous = disks_storage[d]["files"].get(f, "")
        old = len(previous.encode("utf-8"))
        if len(text.encode("utf-8")) - old > disk_free(d):
            p(f"{RED}No queda espacio en {d}:.{RESET}"); return False
        disks_storage[d]["files"][f] = text
        name = f"{d}:{f}"
        p(f"{GREEN}Guardado en {d}:\\{f}{RESET}")
        return True

    listing()
    while True:
        try:
            line = ask(f"{GREEN}sc> {RESET}")
        except EOFError:
            return
        s = line.strip()
        if not s.startswith("."):
            if s:
                prog.append(s)
                listing()
            continue
        parts = s.split(maxsplit=2)
        c = parts[0].lower()
        a1 = parts[1] if len(parts) > 1 else ""
        a2 = parts[2] if len(parts) > 2 else ""
        if c in (".salir", ".exit", ".q"):
            return
        elif c in (".ayuda", ".help"):
            clr()
            for h in SC_HELP_TEXT: p(h)
        elif c in (".lista", ".list", ".l"):
            listing()
        elif c in (".run", ".ejecutar", ".r", ".verificar", ".probar"):
            clr()
            p(f"{CYAN}▶ Ejecutando...{RESET}")
            try:
                cmds = sc_run("\n".join(prog), out=p, inp=ask, clear=clr, origin=name or "(ide)")
                p(f"{GREEN}■ Programa terminado.{RESET}")
                if cmds:
                    p(f"{GREEN}Comandos nuevos disponibles en Serpent OS: {', '.join(cmds)}{RESET}")
                    if not name:
                        p(f"{YELLOW}Guárdalo (.guardar NOMBRE) para que el comando siga tras reiniciar.{RESET}")
            except SCError as e:
                p(f"{RED}✗ Error en {e}{RESET}")
                if e.line and 0 < e.line <= len(prog):
                    p(f"{YELLOW}  {e.line}: {prog[e.line - 1]}{RESET}")
            p(f"{CYAN}(Escribe otra línea o usa .verificar para volver a ejecutar){RESET}")
            try: ask("")
            except EOFError: return
            listing()
        elif c in (".borrar", ".del") and a1.isdigit() and 1 <= int(a1) <= len(prog):
            prog.pop(int(a1) - 1); listing()
        elif c in (".editar", ".edit") and a1.isdigit() and 1 <= int(a1) <= len(prog) and a2:
            prog[int(a1) - 1] = a2; listing()
        elif c in (".insertar", ".ins") and a1.isdigit() and 1 <= int(a1) <= len(prog) + 1 and a2:
            prog.insert(int(a1) - 1, a2); listing()
        elif c == ".nuevo":
            prog, name = [], None; listing()
        elif c in (".guardar", ".save"):
            target = a1 or (name or "")
            if not target:
                p(f"{YELLOW}Uso: .guardar NOMBRE{RESET}")
            else:
                save(target)
        elif c in (".abrir", ".open") and a1:
            d, f = resolve_path(a1)
            f = f.upper()
            if not f.endswith(SC_EXT): f += SC_EXT
            files = disks_storage.get(d, {}).get("files", {})
            if f in files:
                prog, name = files[f].splitlines(), f"{d}:{f}"; listing()
            else:
                p(f"{RED}No existe {d}:\\{f}. Mira .archivos{RESET}")
        elif c in (".archivos", ".files"):
            found = list(_sc_all_files())
            p(f"{CYAN}Programas SerpentC:{RESET}" if found else f"{YELLOW}Aún no hay programas .SC guardados.{RESET}")
            for d, f, content in found:
                p(f"  {d}:\\{f}  ({len(content)} bytes)")
        elif c == ".ejemplo" and a1.upper() in SC_EXAMPLES:
            prog, name = SC_EXAMPLES[a1.upper()].splitlines(), None; listing()
            p(f"{GREEN}Ejemplo cargado. Escribe .run para probarlo.{RESET}")
        else:
            p(f"{YELLOW}Orden no reconocida. Escribe .ayuda{RESET}")


def _sc_run_in_window(title, fn):
    """Ejecuta fn(io) en la ventana de Serpent OS si hay ratón; si no, en la terminal."""
    if _gui_available():
        win = _GameWindow(title)
        io = {"print": win.print, "input": win.input, "clear": win.clear}
        print(f"{YELLOW}Abriendo ventana...{RESET}")
        try:
            win.run(lambda: KERNEL.run_user("SERPENTC", lambda: fn(io)))
        except Exception as e:
            print(f"{RED}La ventana se cerró por un error: {e}{RESET}")
    else:
        io = {"print": builtins.print, "input": builtins.input, "clear": clear_screen}
        try:
            fn(io)
        except (KeyboardInterrupt, EOFError):
            print()


def cmd_serpentc(args=""):
    _sc_run_in_window("SerpentC IDE", lambda io: _sc_ide(io, args.strip() or None))
    print(f"{CYAN}Volviendo a Serpent OS...{RESET}\n")


def cmd_scrun(args=""):
    a = args.split(maxsplit=1)
    if not a:
        print(f"{RED}Uso: scrun [u:]programa [argumentos]{RESET}"); return
    d, f = resolve_path(a[0])
    f = f.upper()
    if not f.endswith(SC_EXT): f += SC_EXT
    files = disks_storage.get(d, {}).get("files", {})
    if f not in files:
        print(f"{RED}No existe {d}:\\{f}. Crea uno con 'serpentc'.{RESET}"); return
    try:
        cmds = sc_run(files[f], clear=clear_screen, args=a[1] if len(a) > 1 else "", origin=f"{d}:{f}")
        if cmds:
            print(f"{GREEN}Comandos instalados: {', '.join(cmds)}{RESET}")
    except SCError as e:
        print(f"{RED}Error SerpentC en {d}:\\{f}, {e}{RESET}")
    except KeyboardInterrupt:
        print(f"\n{YELLOW}Programa interrumpido.{RESET}")


def cmd_sccmds(args=""):
    _sc_autoload()
    if not SC_USER_COMMANDS:
        print(f"{YELLOW}Aún no has creado comandos. Prueba 'serpentc' y luego .ejemplo saludo{RESET}"); return
    panel("COMANDOS CREADOS CON SERPENTC")
    for n, origin in sorted(SC_USER_COMMANDS.items()):
        print(f"  {MAGENTA}{n:<16}{RESET} definido en {origin}")


