def _sc_capture(src, inputs, args=""):
    buf, q = [], list(inputs)

    def o(*a, end="\n", **k):
        buf.append(" ".join(str(x) for x in a) + end)

    def i(p=""):
        buf.append(str(p))
        if not q:
            raise SCError("el programa pidió más datos de los esperados")
        v = q.pop(0); buf.append(v + "\n"); return v
    cmds = sc_run(src, out=o, inp=i, register=False, args=args)
    return re.sub(r"\x1b\[[0-9;]*m", "", "".join(buf)), cmds


def _sc_check(lesson, src):
    if lesson["check"] == "cmd":
        cmds = sc_compile(src)[2]
        if "eco2" not in cmds:
            return False, "No veo  comando eco2"
        sc_run(src, out=lambda *a, **k: None, register=False)
        # probar el comando de verdad
        try:
            out, _ = _sc_capture(src.replace("comando eco2", "funcion eco2_prueba(argumentos)", 1)
                                 + "\neco2_prueba(partir(\"hola serpiente\"))", [])
        except SCError as e:
            return False, str(e)
        return (out.count("hola serpiente") >= 2, "Debe mostrar los argumentos dos veces")
    if lesson["check"] is None:          # lección 'si'
        a, _ = _sc_capture(src, ["15"])
        b, _ = _sc_capture(src, ["3"])
        ok = "Grande" in a and "Pequeño" in b and "Pequeño" not in a.split("Número")[-1].replace("Pequeño?", "")
        return ok and "Grande" not in b, "Con 15 debe salir Grande y con 3 Pequeño"
    out, _ = _sc_capture(src, lesson["inputs"])
    return lesson["check"](out, src), "La salida no es la esperada:\n" + out.strip()[:300]


def _sc_read_block(prompt_fn):
    lines = []
    while True:
        l = prompt_fn(f"{GREEN}{len(lines) + 1:>2}| {RESET}")
        if l.strip().lower() in (".verificar", ".comprobar", "."):
            return "\n".join(lines)
        if l.strip().lower() in (".salir", ".q"):
            return None
        if l.strip() == ".borrar" and lines:
            lines.pop(); print(f"{YELLOW}(última línea borrada){RESET}"); continue
        lines.append(l)


def cmd_aprende(args=""):
    prog = system_state.setdefault("sc_progress", 0) if isinstance(system_state, dict) else 0
    a = args.strip()
    if a.isdigit():
        prog = max(0, min(len(SC_LESSONS) - 1, int(a) - 1))
    elif a == "reiniciar":
        prog = 0
    panel("APRENDE SERPENTC DESDE CERO")
    print(f"  {len(SC_LESSONS)} lecciones · vas por la {min(prog + 1, len(SC_LESSONS))}. 'aprende N' salta a una lección.")
    print(f"  Escribe tu código línea a línea. Cuando termines, escribe {YELLOW}.verificar{RESET} y pulsa Enter.")
    print(f"  {YELLOW}.borrar{RESET} quita la última línea · {YELLOW}.salir{RESET} sale del curso\n")
    while prog < len(SC_LESSONS):
        L = SC_LESSONS[prog]
        print(f"{CYAN}══ Lección {prog + 1}/{len(SC_LESSONS)}: {YELLOW}{L['t']}{CYAN} ══{RESET}")
        for x in L["x"]:
            print("  " + x)
        print(f"\n  {MAGENTA}Ejemplo:{RESET}")
        for l in L["e"].splitlines():
            print(f"    {GREEN}{l}{RESET}")
        try:
            demo, _ = _sc_capture(L["e"], ["Ana" if "nombre" in L["e"] else "20"])
            print(f"  {MAGENTA}Resultado:{RESET}")
            for l in demo.strip().splitlines()[:8]:
                print(f"    {l}")
        except Exception:
            pass
        print(f"\n  {YELLOW}► Reto:{RESET} {L['task']}")
        while True:
            try:
                src = _sc_read_block(builtins.input)
            except (EOFError, KeyboardInterrupt):
                src = None
            if src is None:
                print(f"{CYAN}Progreso guardado. Vuelve con 'aprende'.{RESET}\n")
                if isinstance(system_state, dict): system_state["sc_progress"] = prog
                return
            try:
                ok, why = _sc_check(L, src)
            except SCError as e:
                ok, why = False, f"Error en {e}"
            if ok:
                print(f"{GREEN}✔ ¡Perfecto! Lección superada.{RESET}\n")
                prog += 1
                if isinstance(system_state, dict): system_state["sc_progress"] = prog
                time.sleep(0.5)
                break
            print(f"{RED}✗ Aún no. {why}{RESET}")
            print(f"{YELLOW}  Inténtalo otra vez (o .salir).{RESET}")
    print(f"{GREEN}🐍 ¡Terminaste el curso! Ya sabes programar en SerpentC.{RESET}")
    print(f"  Abre {YELLOW}serpentc{RESET} y crea tus propios comandos para Serpent OS.\n")


