# =====================================================================
#  SERPENT OS 6.0 - Descubrimiento de comandos
#  "which" indica qué componente ejecutará una orden y sigue alias.
# =====================================================================

def cmd_which(args=""):
    """Identifica comandos, alias, extensiones SerpentC y scripts .BAT/.SH."""
    try:
        names = shlex.split(args)
    except ValueError as exc:
        print(f"{RED}Sintaxis no válida: {exc}{RESET}")
        return
    if not names:
        print(f"{RED}Uso: which comando [comando2 ...]{RESET}")
        return

    core = {
        "help", "clear", "cls", "date", "disk", "mount", "dir", "ls",
        "edit", "read", "format", "ps", "kill", "browser", "store",
        "games", "run", "apps", "matrix", "rpg", "shop", "oraculo",
        "oráculo", "god", "himno", "templo", "about", "whoami",
        "exit", "shutdown", "reboot", "restart", "logout", "bat",
        "tour", "gui",
    }
    user_aliases = system_state.get("aliases", {})
    for original in names:
        name = original.lower()
        current = name
        chain = []
        seen = set()

        # Primero sigue alias del usuario y luego alias compatibles del shell.
        while current not in seen:
            seen.add(current)
            target = user_aliases.get(current)
            source = "alias personal"
            if target is None:
                target = SHELL_ALIASES.get(current)
                source = "alias del sistema"
            if target is None:
                break
            chain.append((current, target, source))
            try:
                current = shlex.split(target)[0].lower()
            except (ValueError, IndexError):
                current = ""
                break

        if chain:
            for alias_name, target, source in chain:
                print(f"{CYAN}{alias_name}{RESET} -> {YELLOW}{target}{RESET} ({source})")

        if not current:
            continue
        if current in core:
            print(f"{GREEN}{original}{RESET}: comando integrado de Serpent OS")
        elif current in EXTRA_COMMANDS:
            print(f"{GREEN}{original}{RESET}: extensión/comando del sistema")
        elif current in FILTERS:
            print(f"{GREEN}{original}{RESET}: filtro de tuberías")
        elif current in SC_USER_COMMANDS:
            print(f"{GREEN}{original}{RESET}: comando SerpentC ({SC_USER_COMMANDS[current]})")
        else:
            drive, filename = _find_script(current)
            if drive is not None:
                print(f"{GREEN}{original}{RESET}: script ejecutable {drive}:\\{filename}")
            elif current in seen and len(seen) > 1:
                print(f"{RED}{original}{RESET}: cadena de alias circular o inválida")
            else:
                print(f"{RED}{original}{RESET}: no se encontró")


# Registro de "which" (Serpent OS 6.0).
EXTRA_COMMANDS["which"] = cmd_which
